"use strict";exports.id=4786,exports.ids=[4786],exports.modules={24786:(a,b,c)=>{c.d(b,{D:()=>d,c:()=>e});let d=[{slug:"medical-billing-coding",title:"Medical Billing and Coding",shortTitle:"Medical Billing & Coding",icon:"\uD83D\uDDC2️",accent:"from-teal-700 to-teal-900",description:"Learn how a clinical encounter becomes a paid claim: the revenue cycle, medical terminology, ICD-10-CM diagnosis coding, and the compliance rules that govern all of it.",overview:"Medical billing and coding sits between the exam room and the payer. Coders translate documented care into standardized codes; billers turn those codes into claims and pursue them until they are resolved. This coursework builds both sides, starting from the revenue cycle as a whole so that every later topic has somewhere to attach. Every lesson works from documentation rather than assumption, because that is the rule the entire field runs on.",outcomes:["Explain the healthcare revenue cycle and identify where revenue is typically lost","Decode medical terminology from its root, prefix, and suffix parts","Describe the structure of ICD-10-CM codes and apply the official coding guidelines","Use the Alphabetic Index and Tabular List together, as the guidelines require","Distinguish upcoding from undercoding and explain why both are compliance problems","Read a denial report and identify which phase of the revenue cycle owns each cause","Select CPT and HCPCS codes, and apply modifiers correctly","Code office visits using medical decision making or total time","Verify eligibility, obtain prior authorization, and use an ABN appropriately","Complete a CMS-1500, distinguish a rejection from a denial, and post a remittance","Prioritize a denial queue by deadline and recoverable value, and write an appeal","Apply HIPAA's minimum necessary standard, and recognize the line between error and fraud"],careerRoles:["Medical biller","Medical coder","Patient accounts representative","Revenue cycle specialist","Medical office administrative assistant"],credentialNote:"This coursework builds the knowledge base for entry-level billing and coding work and helps prepare for a certification exam. It is not itself a certification, and it does not replace a current code set. ICD-10-CM is revised every October and CPT every January, so always work from the current year's official code books and guidelines rather than from any course material, including this one. Certification is awarded by the credentialing bodies below, each of which sets its own eligibility requirements.",relatedCertifications:[{name:"CPC — Certified Professional Coder",body:"AAPC",note:"Physician-practice focused; the most widely held outpatient coding credential."},{name:"CCA — Certified Coding Associate",body:"AHIMA",note:"Entry-level credential across care settings."},{name:"CCS — Certified Coding Specialist",body:"AHIMA",note:"Hospital and inpatient focused; expects more experience."},{name:"CBCS — Certified Billing and Coding Specialist",body:"NHA",note:"Billing-weighted entry-level credential."}],modules:[{moduleNumber:1,moduleSlug:"module-1",title:"The Revenue Cycle",emoji:"\uD83D\uDD04",description:"How a clinical encounter becomes a paid claim, who the parties are, and where practices actually lose money.",lessons:[{slug:"what-billing-and-coding-is",title:"What Medical Billing and Coding Actually Is",description:"Understand the two distinct jobs behind the title, how they relate, and why a clinic cannot get paid without both being done well.",duration:"20 min",objectives:["Explain the difference between medical coding and medical billing","Describe how a clinical encounter becomes a paid claim","Name the parties involved in a healthcare transaction and what each one wants","Explain why coding accuracy is a compliance issue and not only a payment issue"],sections:[{heading:"Two jobs, one title",blocks:[{type:"scenario",role:"You are starting as a billing specialist at Lakeside Medical Associates.",text:"A patient sees Dr. Okafor for persistent knee pain. The visit lasts twenty minutes, the provider examines the knee, orders an X-ray, and diagnoses osteoarthritis. Clinically the encounter is finished. Financially nothing has happened at all — and unless someone translates that visit into a specific set of codes and sends it to the right payer in the right format within the right window, the practice will never be paid for it.",task:"Understand the pipeline that turns a documented visit into money in the practice's account, and where you sit in it."},{type:"paragraph",text:"The job title joins two related but genuinely different roles. A medical coder reads the clinical documentation and translates what happened into standardized codes: a diagnosis code describing the patient's condition, and a procedure code describing what the provider did. A medical biller takes those codes, attaches the patient's insurance information, produces a claim, submits it to the payer, and pursues it until it is paid or properly resolved."},{type:"paragraph",text:"In a large hospital these are separate departments. In a practice the size of Lakeside, one person often does both, which is why the training covers both. The skills differ: coding rewards precision, patience, and comfort with reference material. Billing rewards persistence, organization, and a willingness to make the follow-up phone call nobody else wants to make."},{type:"key-terms",terms:[{term:"Encounter",definition:"A single documented interaction between a patient and a provider. Every claim begins with one."},{term:"Diagnosis code",definition:"A code describing the patient's condition — why care was needed. In the United States these come from ICD-10-CM."},{term:"Procedure code",definition:"A code describing what the provider did — the service delivered. These come from CPT and HCPCS Level II."},{term:"Claim",definition:"The formal request for payment sent to a payer, carrying the codes, the provider's identifiers, and the patient's coverage information."},{term:"Payer",definition:"Whoever is being asked to pay — a commercial insurer, Medicare, Medicaid, or in some cases the patient directly."},{term:"Reimbursement",definition:"The payment a payer makes for a covered service, which is usually a contracted rate rather than the amount billed."}]}]},{heading:"The pipeline from visit to payment",blocks:[{type:"paragraph",text:"The sequence below is the backbone of the entire field. Every later module in this program is a detailed treatment of one or two of these steps, so it is worth learning the shape of the whole thing before going deeper into any part of it."},{type:"table",caption:"How an encounter becomes revenue",columns:["Step","What happens","Who does it"],rows:[["1. Pre-registration","Demographics and insurance are captured and verified before the visit","Front desk"],["2. Eligibility and authorization","Coverage is confirmed; prior authorization obtained if the payer requires it","Front desk or billing"],["3. The encounter","The provider delivers and documents care","Provider"],["4. Coding","Documentation is translated into diagnosis and procedure codes","Coder"],["5. Charge entry","Codes and charges are entered into the practice management system","Biller or coder"],["6. Claim scrubbing","The claim is checked against payer rules before it goes out","Billing software and biller"],["7. Submission","The claim is transmitted, usually electronically through a clearinghouse","Biller"],["8. Adjudication","The payer decides what to pay, reduce, or deny","Payer"],["9. Payment posting","Payment and adjustments are recorded against the account","Biller"],["10. Denial follow-up","Denied or underpaid claims are corrected, appealed, or written off","Biller"],["11. Patient billing","The remaining patient responsibility is billed and collected","Biller"]]},{type:"callout",variant:"info",text:"Notice that steps 1 and 2 happen before the patient is ever seen. A large share of denials trace back to something that went wrong at the front desk — an expired policy, a transposed member number, a missing authorization. Billing problems are very often registration problems that took three weeks to become visible."}]},{heading:"Why accuracy is a compliance matter",blocks:[{type:"paragraph",text:"It is tempting to think of coding as a revenue exercise where higher codes are better. That framing is both wrong and genuinely dangerous. A code is a factual assertion about what happened to a patient, submitted to a payer that may be a federal program. Submitting a code the documentation does not support is a false claim, and the consequences are not limited to the money being recouped."},{type:"table",caption:"The two ways coding goes wrong",columns:["Error","What it means","Consequence"],rows:[["Upcoding","Reporting a more complex or expensive service than was documented","Overpayment recovery, penalties under the False Claims Act, exclusion from federal programs"],["Undercoding","Reporting a lower level of service than was documented","Lost revenue, and a distorted record of the patient's care and the practice's case mix"]]},{type:"paragraph",text:"Undercoding is sometimes treated as the safe error. It is not. It misrepresents the care delivered just as upcoding does, it starves the practice of revenue it legitimately earned, and a pattern of it can itself attract attention. The goal is never the highest code or the lowest code. It is the code the documentation supports."},{type:"callout",variant:"warning",text:"The governing principle of this entire field is one sentence: if it was not documented, it was not done. A coder codes from the documentation, not from what they assume happened, not from what the provider says in the hallway, and not from what would pay better. When the documentation does not support a code, the correct action is to query the provider — never to code what you believe they meant."},{type:"knowledge-check",question:"A provider tells you verbally that an office visit involved a detailed examination, but the note in the chart documents only a brief exam. What should you do?",options:["Code the higher level of service, since the provider confirmed what happened","Code from the documentation as written, and query the provider to amend the note if the exam was more extensive","Code the lower level and say nothing, since undercoding is always safe","Split the difference and code a mid-level visit"],correctIndex:1,explanation:"Coders code from the documentation. If the record does not support the higher level, the fix is a provider query that gives the provider the opportunity to amend the note properly — not a coding decision that papers over the gap. If the note is amended appropriately, the higher code becomes supportable; if it is not amended, the documented level stands.",optionRationales:["A verbal statement is not documentation. Coding above what the record supports is upcoding, regardless of what you were told.","Correct. Code what is documented, and query the provider so the record can be corrected through the proper process if the care was genuinely more extensive.","Undercoding is not safe. It misrepresents the encounter and costs the practice revenue it legitimately earned, and doing it knowingly is its own problem.","There is no averaging in coding. The level of service is determined by what the documentation supports, not by compromise."]}]}],challenge:[{type:"paragraph",text:"Trace a single encounter through the whole pipeline in writing, in your own words."},{type:"list",ordered:!0,items:["Invent a straightforward encounter: a patient with a sore throat sees a provider, who examines them and performs a rapid strep test. Write three sentences describing what happened clinically.","For each of the eleven pipeline steps, write one sentence describing what happens to this specific encounter at that step. Where you do not yet know the detail, write what question you would need answered.","Identify the two steps in your list where you think an error would be most expensive to fix later, and explain why in a sentence each.","Write down one question about this pipeline that you cannot yet answer. Keep the list — by the end of this program you should be able to answer it, and checking back is a good measure of your progress."]}]},{slug:"the-revenue-cycle",title:"The Revenue Cycle and Where Money Is Lost",description:"Follow the money through a medical practice, and learn where revenue actually leaks — usually far earlier in the process than people expect.",duration:"20 min",objectives:["Define the revenue cycle and its front-end, middle, and back-end phases","Explain what a clean claim is and why the first-pass rate matters","Interpret days in accounts receivable as a measure of practice health","Identify the front-end failures that cause the majority of back-end denials"],sections:[{heading:"Revenue cycle management",blocks:[{type:"scenario",role:"You review last quarter's numbers at Lakeside Medical Associates.",text:"The practice billed $840,000 and collected $611,000. The gap is not one large problem. It is roughly nine hundred small ones: claims denied for eligibility, claims paid at a lower rate than expected, patient balances never collected, and a stack of claims that quietly aged past the filing deadline and can no longer be submitted at all.",task:"Learn to see the revenue cycle as a system with measurable leak points, rather than as a pile of individual claims."},{type:"paragraph",text:"Revenue cycle management is the discipline of running that whole pipeline as a system. The important insight — and it is genuinely counter-intuitive when you start — is that most revenue is lost at the front end, but the loss only becomes visible at the back end, weeks later, when a denial arrives."},{type:"table",caption:"The three phases",columns:["Phase","Covers","Typical failure"],rows:[["Front end","Scheduling, registration, eligibility, authorization, point-of-service collection","Wrong or expired insurance captured; authorization never obtained"],["Middle","Clinical documentation, coding, charge capture","A service delivered but never charged; documentation that does not support the code"],["Back end","Claim submission, payment posting, denials, appeals, patient collections","Claims not worked before the filing deadline; denials written off instead of appealed"]]}]},{heading:"The measures that tell you the truth",blocks:[{type:"paragraph",text:"A practice's billing health can be read from a handful of numbers. Learning to interpret them is what separates someone who processes claims from someone who can tell a practice manager what is actually wrong."},{type:"table",caption:"Core revenue cycle metrics",columns:["Metric","What it measures","What good looks like"],rows:[["Clean claim rate","Share of claims accepted on first submission with no edits","Commonly targeted at 95% or better"],["First-pass resolution rate","Share of claims paid on the first submission","Higher is better; a low rate points to front-end or coding problems"],["Days in A/R","Average days from service to payment","Often targeted under 40 days for a physician practice"],["A/R over 90 days","Share of receivables aged past 90 days","Commonly targeted under 15-20%; older debt is much harder to collect"],["Denial rate","Share of claims denied","Frequently targeted under 5-10%"],["Net collection rate","Share of collectible revenue actually collected","Often targeted at 95% or better"]]},{type:"callout",variant:"info",text:"These benchmarks vary by specialty, payer mix, and who is publishing them, so treat them as orientation rather than as fixed standards. What matters more than hitting any specific number is the trend: a denial rate climbing from 6% to 11% over two quarters is a problem worth investigating regardless of what the industry average happens to be."},{type:"worked-example",title:"Reading a denial report",task:"Last month Lakeside submitted 1,200 claims. 138 were denied. Sorted by reason: 61 eligibility or coverage, 29 missing prior authorization, 22 missing or invalid information, 14 non-covered service, 12 coding errors. Where is the actual problem?",steps:[{move:"Calculate the denial rate: 138 of 1,200 is 11.5%.",why:"The rate frames the size of the problem before you look at causes. At 11.5%, roughly one claim in nine is failing — well above where most practices want to be, and enough to explain a meaningful revenue gap on its own."},{move:"Group the reasons by which phase of the cycle owns them.",why:"Eligibility, authorization, and missing information are all front-end failures. That is 112 of 138 denials — over 80% — originating before the patient was ever seen. Only 12 are coding errors."},{move:"Resist the instinct to retrain the coders.",why:"Coding is the smallest category here, and it is where people usually look first because it is the most visible. The data says the leverage is at registration and authorization. Fixing the right 20% of the problem while ignoring the 80% is a common and expensive mistake."},{move:"Convert the finding into a specific front-desk change.",why:"Verifying eligibility electronically at scheduling and again at check-in addresses the largest single category. A recommendation naming the step, the owner, and the expected effect is actionable; 'we should reduce denials' is not."}],result:"A recommendation to add a two-point eligibility check at the front desk, targeting the 61 eligibility denials and a share of the 29 authorization denials.",takeaway:"Denials surface at the back end and originate at the front end. Always group denial reasons by the phase that caused them before deciding what to fix."},{type:"knowledge-check",question:"A practice has a denial rate of 12%, and most denials cite eligibility or missing authorization. Where should improvement effort be focused?",options:["On the coding team, since coding accuracy drives claim acceptance","On the front-end registration and verification process, where those denials originate","On hiring more staff to work denials after they arrive","On appealing every denial more aggressively"],correctIndex:1,explanation:"Eligibility and authorization denials are caused before the encounter, at registration and scheduling. Working them after the fact is expensive rework; verifying coverage and obtaining authorization up front prevents the denial from ever being generated.",optionRationales:["Coding is not implicated by these denial reasons. Retraining coders would not touch the actual cause.","Correct. These denials originate at the front end, so that is where the fix belongs.","More staff working denials treats the symptom. It increases cost without reducing the number of denials generated.","Appeals recover some revenue but are slow and often unsuccessful for eligibility denials — if coverage genuinely was not active, there is nothing to appeal."]}]}],challenge:[{type:"paragraph",text:"Practice reading the numbers rather than the individual claims."},{type:"list",ordered:!0,items:["A practice submits 800 claims in a month. 736 are accepted on first submission. Calculate the clean claim rate and state whether it meets a 95% target.","Total A/R is $412,000, of which $94,000 is over 90 days old. Calculate the percentage over 90 days and say whether it falls inside a 15-20% target range.","Denials for the month: 34 eligibility, 18 authorization, 11 duplicate claim, 9 coding, 6 non-covered. Group them by revenue cycle phase and state which phase owns the largest share.","Write a three-sentence recommendation to the practice manager naming the single change you would make first, the denial categories it would affect, and how you would measure whether it worked."]}]},{slug:"the-players-and-their-rules",title:"Payers, Providers, and Patients",description:"Learn who the parties in a healthcare transaction are, what each one is trying to achieve, and why the rules differ so much between them.",duration:"18 min",objectives:["Describe the main payer types and how they differ","Explain the difference between in-network and out-of-network status","Define deductible, copayment, coinsurance, and out-of-pocket maximum","Explain why the billed amount is rarely the amount anyone pays"],sections:[{heading:"Who is actually in the transaction",blocks:[{type:"scenario",role:"You explain a bill to a patient at Lakeside Medical Associates.",text:"A patient calls, upset. The practice billed $340 for her visit. Her insurer's statement says the allowed amount was $186, the plan paid $148.80, and she owes $37.20. She wants to know why there are four different numbers for one appointment, and whether she is being overcharged.",task:"Understand the money well enough to explain it clearly and correctly to the person paying it."},{type:"paragraph",text:"Healthcare billing is unusual because the person receiving the service is usually not the person paying for it, and the price is set by a contract neither of them read. Untangling that is most of what makes a bill confusing, and being able to explain it plainly is one of the most valuable things a billing specialist does."},{type:"key-terms",terms:[{term:"Billed amount",definition:"What the practice charges. Largely a starting figure — for contracted payers it is rarely what anyone actually pays."},{term:"Allowed amount",definition:"The maximum the payer's contract permits for that service. This is the real price."},{term:"Contractual adjustment",definition:"The difference between billed and allowed, which an in-network provider agrees to write off and may not bill to the patient."},{term:"Deductible",definition:"What the patient pays before the plan begins paying at all, usually reset each plan year."},{term:"Copayment",definition:"A fixed amount the patient pays per visit, such as $30 for an office visit."},{term:"Coinsurance",definition:"A percentage of the allowed amount the patient pays after the deductible, such as 20%."},{term:"Out-of-pocket maximum",definition:"The annual ceiling on the patient's own spending, after which the plan covers 100% of covered services."}]},{type:"worked-example",title:"Explaining the four numbers",task:"Explain to the patient why a $340 charge produced a $37.20 bill, and confirm whether she was overcharged.",steps:[{move:"Start with the allowed amount, not the billed amount.",why:"The $340 is the practice's standard charge, but the insurer's contract sets the allowed amount at $186. That contract is what governs. Leading with this reframes the conversation from 'why so much' to 'here is what your plan agreed to.'"},{move:"Name the contractual adjustment: $340 − $186 = $154 written off.",why:"This is money the practice does not collect from anyone. Patients frequently assume they are being billed the full charge, and hearing that $154 was removed by the insurance contract usually resolves most of the concern immediately."},{move:"Split the allowed amount: plan pays $148.80, patient owes $37.20.",why:"$37.20 is exactly 20% of $186, so this is 20% coinsurance on a met deductible. Naming the mechanism lets the patient check it against their own plan documents rather than taking your word for it."},{move:"Confirm the answer to what she actually asked.",why:"She asked whether she was overcharged. The answer is no, and saying so directly matters — walking through arithmetic without answering the question leaves the patient still worried. Then offer to review it again if her plan documents show different cost-sharing."}],result:"The patient understands the $37.20 is her plan's 20% coinsurance on a contracted rate, and that $154 was written off.",takeaway:"The allowed amount is the real price. Explain the contractual adjustment early — it is usually the number that resolves the patient's concern."}]},{heading:"Payer types and why the rules differ",blocks:[{type:"table",caption:"Main payer categories",columns:["Payer","Covers","Note for billers"],rows:[["Commercial insurance","Employer-sponsored and individual plans","Rules vary by plan, not just by insurer — always check the specific plan"],["Medicare","Adults 65+, and some younger people with disabilities or ESRD","Federal rules; Part A covers inpatient, Part B outpatient and professional services"],["Medicaid","Low-income individuals and families","Administered by states, so rules and covered services differ substantially by state"],["Medicare Advantage (Part C)","Medicare benefits delivered by a private plan","Follows the plan's rules, not traditional Medicare's — a very common source of confusion"],["TRICARE","Military members, retirees, and their families","Its own authorization and referral requirements"],["Workers' compensation","Work-related injury and illness","Not health insurance; separate claim forms, rules, and fee schedules"],["Self-pay","No insurance, or a non-covered service","Discuss cost before service; many practices offer a discounted self-pay rate"]]},{type:"paragraph",text:"In-network means the provider has a contract with the payer setting agreed rates and requiring the provider to write off the difference. Out-of-network means no such contract, so the payer covers less or nothing, and the patient is exposed to a much larger balance. Verifying network status is part of eligibility verification, and it is one of the most consequential things checked at the front desk."},{type:"callout",variant:"warning",text:"Balance billing — charging a patient the difference between your charge and the allowed amount — is prohibited for in-network services and, under the federal No Surprises Act, for many out-of-network emergency and ancillary situations as well. The rules are detailed and state law adds more. Never tell a patient they owe a balance without confirming it is permitted, and escalate anything you are unsure about."},{type:"knowledge-check",question:"A practice bills $500 for a service. The payer's allowed amount is $300, the plan pays $240, and the patient owes $60. What is the $200 difference between the billed and allowed amounts called, and who pays it?",options:["Coinsurance, paid by the patient","A contractual adjustment, which the in-network provider writes off and bills to no one","The deductible, paid by the patient before coverage begins","A denial, which the provider must appeal to recover"],correctIndex:1,explanation:"The gap between billed and allowed is the contractual adjustment. By contracting with the payer, the in-network provider agrees to accept the allowed amount as payment in full and to write off the difference. Billing that $200 to the patient would be prohibited balance billing.",optionRationales:["Coinsurance is the patient's percentage share of the allowed amount — here the $60, not the $200.","Correct. The $200 is a contractual write-off the provider absorbs under its contract with the payer.","A deductible is what the patient pays before the plan begins paying. It comes out of the allowed amount, not from the gap above it.","Nothing was denied. The payer processed the claim and paid according to the contract."]}]}],challenge:[{type:"paragraph",text:"Work through the patient responsibility calculation, which you will do constantly in this job."},{type:"list",ordered:!0,items:["A patient has a $1,500 annual deductible, of which $1,200 is met, and 20% coinsurance. A service has an allowed amount of $800. Calculate how much the patient owes and how much the plan pays. Show your steps.","The same patient has an out-of-pocket maximum of $4,000 and has paid $3,850 so far this year. Recalculate what they owe for the same $800 service, and explain what changed.","Write a short script — no more than four sentences — explaining the first calculation to the patient on the phone in plain language, without using the word 'coinsurance' until you have defined it.","Name two things you would verify at registration that would prevent this patient from receiving an unexpected bill."]}]}],level:"Beginner",estimatedMinutes:58,whatYoullLearn:["The difference between medical coding and medical billing","The eleven steps from patient registration to collected payment","The metrics that reveal a practice's billing health","Payer types, network status, and how patient responsibility is calculated"],scenario:"Lakeside Medical Associates billed $840,000 last quarter and collected $611,000. The gap is not one large problem but roughly nine hundred small ones — denied claims, underpayments, uncollected patient balances, and claims that quietly aged past the filing deadline. Your first job is to understand the system well enough to see where the money is going."},{moduleNumber:2,moduleSlug:"module-2",title:"Medical Terminology for Coders",emoji:"\uD83D\uDD24",description:"Decode medical terms from their parts, and map conditions to the body systems that organize the code books.",lessons:[{slug:"word-parts",title:"Building Medical Terms from Parts",description:"Learn the root, prefix, and suffix system that lets you decode medical terms you have never seen before, instead of memorizing them one at a time.",duration:"22 min",objectives:["Break a medical term into root, prefix, suffix, and combining vowel","Decode an unfamiliar term from its parts","Recognize the high-frequency prefixes and suffixes used in diagnosis codes","Distinguish terms that differ by a single letter but mean very different things"],sections:[{heading:"Why coders learn terminology",blocks:[{type:"scenario",role:"You are coding a chart at Lakeside Medical Associates.",text:"The note reads: 'Patient presents with pericarditis; history of pericardiocentesis in 2023. No evidence of endocarditis.' You must code the current condition and not the history, and not the condition that was explicitly ruled out. Getting that right depends on reading three similar-looking words accurately.",task:"Learn the word-part system so unfamiliar terms become decodable rather than intimidating."},{type:"paragraph",text:"Medical terms are assembled from a small set of reusable parts, mostly Greek and Latin. Learning perhaps a hundred parts lets you decode thousands of terms — which is a far better investment than memorizing terms individually, and it is what makes an experienced coder fast."},{type:"table",caption:"The four building blocks",columns:["Part","Position","Carries","Example"],rows:[["Root","Core of the word","The body part or system","cardi- (heart)"],["Prefix","Beginning","Location, number, time, or negation","peri- (around)"],["Suffix","End","The condition, procedure, or process","-itis (inflammation)"],["Combining vowel","Joins parts","Nothing — it only aids pronunciation, usually 'o'","cardi-o-logy"]]},{type:"worked-example",title:"Decoding three similar terms",task:"Work out what pericarditis, pericardiocentesis, and endocarditis each mean, using only the parts.",steps:[{move:"Read the suffix first, because it tells you what kind of word this is.",why:"The suffix says whether you are looking at a condition, a procedure, or a specialty. -itis means inflammation, so pericarditis and endocarditis are conditions. -centesis means surgical puncture to withdraw fluid, so pericardiocentesis is a procedure. That single move already sorts the three terms into two categories."},{move:"Identify the root: cardi- means heart in all three.",why:"The shared root tells you all three concern the heart. Recognizing the constant lets you focus on what actually differs, which is where the meaning separates."},{move:"Read the prefix, which is what distinguishes them.",why:"peri- means around, so pericarditis is inflammation of the sac around the heart. endo- means within, so endocarditis is inflammation of the heart's inner lining. Same root, same suffix, completely different diagnoses — and different codes."},{move:"Reassemble and sanity-check against the note.",why:"Pericarditis is the current diagnosis and gets coded. Pericardiocentesis is a past procedure, which is history rather than a current condition. Endocarditis was ruled out, and in the outpatient setting a ruled-out condition is not coded. Decoding correctly is what prevents all three from being treated the same way."}],result:"Only the pericarditis is coded as the current condition; the procedure is history and the ruled-out condition is not coded.",takeaway:"Read the suffix, then the root, then the prefix. The prefix is very often the only thing separating two conditions that are coded quite differently."}]},{heading:"The parts worth memorizing first",blocks:[{type:"table",caption:"High-frequency prefixes",columns:["Prefix","Means","Example"],rows:[["a-, an-","without","anemia — without blood"],["brady-","slow","bradycardia — slow heart rate"],["tachy-","fast","tachycardia — fast heart rate"],["hyper-","above normal, excessive","hypertension — high blood pressure"],["hypo-","below normal, deficient","hypoglycemia — low blood sugar"],["peri-","around","perinatal — around the time of birth"],["endo-","within","endoscopy — viewing within"],["dys-","painful, difficult, abnormal","dysphagia — difficulty swallowing"],["poly-","many","polyuria — excessive urination"],["post-","after","postoperative — after surgery"]]},{type:"table",caption:"High-frequency suffixes",columns:["Suffix","Means","Example"],rows:[["-itis","inflammation","arthritis — joint inflammation"],["-ectomy","surgical removal","appendectomy — removal of the appendix"],["-ostomy","creation of an opening","colostomy — opening into the colon"],["-otomy","cutting into","tracheotomy — incision into the trachea"],["-plasty","surgical repair","rhinoplasty — repair of the nose"],["-scopy","visual examination","colonoscopy — examination of the colon"],["-emia","blood condition","leukemia — white blood cell condition"],["-algia","pain","neuralgia — nerve pain"],["-osis","abnormal condition","osteoporosis — porous bone condition"],["-pathy","disease","neuropathy — nerve disease"]]},{type:"callout",variant:"warning",text:"Three suffixes are frequently confused and mean genuinely different procedures: -otomy is cutting into, -ostomy is creating a permanent opening, and -ectomy is removing. A colotomy, a colostomy, and a colectomy are three different operations with three different codes and very different payments. The single letter matters."},{type:"knowledge-check",question:"What does the term 'hypernatremia' mean, based on its parts?",options:["A deficiency of sodium in the blood","An excess of sodium in the blood","Surgical removal of sodium-producing tissue","Inflammation caused by high sodium"],correctIndex:1,explanation:"hyper- means above normal or excessive, natr- refers to sodium, and -emia means a blood condition. Together: excessive sodium in the blood. Its opposite, hyponatremia, uses hypo- for below normal.",optionRationales:["That is hyponatremia. The prefix hypo- means below normal, where hyper- means above.","Correct. hyper- (excessive) + natr- (sodium) + -emia (blood condition).","Removal would require the suffix -ectomy. The suffix here is -emia, which denotes a blood condition.","Inflammation would require the suffix -itis. -emia denotes a condition of the blood."]}]}],challenge:[{type:"paragraph",text:"Decode rather than memorize. For each term, write the parts and their meanings before writing the definition."},{type:"list",ordered:!0,items:["Break these into parts and define them: gastroenteritis, nephrolithiasis, bronchoscopy, cardiomyopathy, osteoarthritis.","Explain the difference between a gastrotomy, a gastrostomy, and a gastrectomy, and say why a coder must never treat them as interchangeable.","Build the term for each of these: inflammation of the liver; surgical repair of a joint; slow breathing; excessive thirst. Check your answers in a medical dictionary.","Find three terms in any medical document you can access, decode them from their parts, then confirm your reading against a reference. Note any where the parts misled you — those are worth remembering."]}]},{slug:"body-systems-for-coders",title:"Body Systems and Where Codes Live",description:"Map the major body systems to the parts of the code books that describe them, so you know where to look before you start searching.",duration:"20 min",objectives:["Name the major body systems and their primary organs","Connect a documented condition to the body system that governs its code range","Use anatomical direction and position terms correctly","Explain why laterality matters for code selection"],sections:[{heading:"Anatomy as a navigation tool",blocks:[{type:"scenario",role:"You are coding a busy afternoon's charts at Lakeside Medical Associates.",text:"Twelve encounters, twelve different complaints — chest pain, a fractured wrist, a urinary tract infection, uncontrolled diabetes. For each you need to find the right code among roughly seventy thousand. Searching the index alphabetically for every one is slow. Knowing which body system owns the condition narrows the search before you begin.",task:"Learn the systems well enough to know roughly where a code lives before you start looking."},{type:"paragraph",text:"Both ICD-10-CM and CPT are organized largely by body system. Once you know that a condition is cardiovascular, you know approximately where its diagnosis code sits and which section of CPT holds the related procedures. That orientation turns searching into navigating."},{type:"table",caption:"Body systems and their coding territory",columns:["System","Key organs","Typical coding territory"],rows:[["Cardiovascular","Heart, arteries, veins","Hypertension, heart failure, arrhythmias; cardiac procedures in CPT surgery"],["Respiratory","Lungs, trachea, bronchi","Asthma, COPD, pneumonia; bronchoscopy and pulmonary function testing"],["Musculoskeletal","Bones, joints, muscles","Fractures, arthritis, sprains; a large CPT surgery section, heavily laterality-dependent"],["Digestive","Stomach, intestines, liver","Gastritis, hernias, liver disease; endoscopy and colonoscopy"],["Genitourinary","Kidneys, bladder, reproductive organs","UTI, renal disease; urology and gynecology procedures"],["Nervous","Brain, spinal cord, nerves","Seizures, neuropathy, stroke; neurology and neurosurgery"],["Endocrine","Pancreas, thyroid, adrenals","Diabetes, thyroid disorders — very high volume in primary care"],["Integumentary","Skin, hair, nails","Dermatitis, wounds, lesions; lesion excision and repair"]]}]},{heading:"Direction, position, and laterality",blocks:[{type:"paragraph",text:"Clinical documentation uses precise positional language, and misreading it changes the code. These terms are always described relative to anatomical position: the body standing upright, facing forward, palms forward."},{type:"table",caption:"Directional terms",columns:["Term","Means","Example"],rows:[["Anterior / ventral","Toward the front","The sternum is anterior to the heart"],["Posterior / dorsal","Toward the back","The spine is posterior to the stomach"],["Superior","Above","The head is superior to the chest"],["Inferior","Below","The stomach is inferior to the lungs"],["Medial","Toward the midline","The great toe is medial to the little toe"],["Lateral","Away from the midline","The ears are lateral to the nose"],["Proximal","Nearer the point of attachment","The elbow is proximal to the wrist"],["Distal","Farther from the point of attachment","The fingers are distal to the wrist"],["Bilateral","Both sides","Bilateral knee pain"]]},{type:"callout",variant:"warning",text:"Laterality is built into a great many ICD-10-CM codes: separate codes exist for right, left, and in some cases bilateral. A note saying only 'knee pain' without a side forces you to an unspecified code, which pays less and may be denied outright by some payers. Missing laterality is one of the most common reasons a coder needs to query a provider, and one of the easiest documentation problems to fix at the source."},{type:"knowledge-check",question:"A chart documents a fracture of the distal radius. Which bone is fractured, and where along it?",options:["The upper arm bone, near the shoulder","The forearm bone on the thumb side, at the end nearer the wrist","The forearm bone on the little-finger side, at the end nearer the elbow","The wrist bone closest to the hand"],correctIndex:1,explanation:"The radius is the forearm bone on the thumb side. Distal means farther from the point of attachment to the trunk, so the distal radius is the end nearer the wrist. Distal radius fractures are among the most common fractures seen in outpatient practice.",optionRationales:["That describes the humerus, the upper arm bone.","Correct. The radius runs on the thumb side of the forearm, and distal places the fracture at the wrist end.","The ulna is the little-finger-side forearm bone, and proximal rather than distal would place it near the elbow.","Wrist bones are the carpals. The radius is a forearm bone that articulates with them."]}]}],challenge:[{type:"paragraph",text:"Practice mapping documentation to body systems and checking it for the detail a coder needs."},{type:"list",ordered:!0,items:["For each condition, name the body system: cholecystitis, bronchitis, cystitis, dermatitis, myocarditis, nephritis.","Rewrite this vague note so it would support specific coding: 'Patient has pain in the shoulder. Ordered imaging.' Add laterality, specificity of site, and any other detail a coder would need.","A note documents 'bilateral lower extremity edema.' Identify the body region, explain what bilateral tells you, and say why that word affects code selection.","List three questions you would ask a provider whose notes routinely omit laterality, phrased so they are useful rather than accusatory."]}]}],level:"Beginner",estimatedMinutes:42,whatYoullLearn:["How roots, prefixes, and suffixes combine to build medical terms","The high-frequency word parts that appear throughout diagnosis coding","The major body systems and the coding territory each one owns","Directional and laterality terms, and why laterality changes code selection"],scenario:"A chart at Lakeside reads: 'Patient presents with pericarditis; history of pericardiocentesis in 2023. No evidence of endocarditis.' Three similar-looking words, and each is handled completely differently — one is coded, one is history, and one was ruled out. Reading them accurately is the difference between a correct claim and a wrong one."},{moduleNumber:3,moduleSlug:"module-3",title:"ICD-10-CM Diagnosis Coding",emoji:"\uD83E\uDE7A",description:"The structure of a diagnosis code, the two-step lookup the guidelines require, and the conventions that decide which codes may be reported together.",lessons:[{slug:"icd-10-cm-structure",title:"How ICD-10-CM Codes Are Built",description:"Learn the structure of a diagnosis code, what each character position carries, and why specificity determines whether a claim is paid.",duration:"24 min",objectives:["Describe the character structure of an ICD-10-CM code","Explain what the placeholder X is for and when it is required","Use the 7th character extension for injury encounters","Explain why coding to the highest level of specificity is required"],sections:[{heading:"The anatomy of a diagnosis code",blocks:[{type:"scenario",role:"You code an orthopedic follow-up at Lakeside Medical Associates.",text:"A patient returns for a healing wrist fracture. You submit S52.5 and the claim is rejected as an invalid code. Nothing is wrong with your reading of the chart — the code you chose is a category header, not a billable code, and it is missing the characters that say which wrist, what kind of fracture, and which encounter this is.",task:"Learn the code structure well enough to recognize when a code is incomplete before it is submitted."},{type:"paragraph",text:"ICD-10-CM stands for International Classification of Diseases, Tenth Revision, Clinical Modification. It is the diagnosis code set used in the United States, maintained by the CDC's National Center for Health Statistics and CMS, and updated annually with changes effective 1 October."},{type:"table",caption:"Character positions in an ICD-10-CM code",columns:["Position","Type","Carries"],rows:[["1","Letter","The chapter — broad category of disease"],["2","Number","With character 1, forms the category"],["3","Number or letter","Completes the three-character category"],["4","Number or letter","Etiology, anatomic site, severity"],["5","Number or letter","Further specificity, often laterality"],["6","Number or letter","Further specificity"],["7","Letter","Extension — encounter type or episode of care"]]},{type:"paragraph",text:"Codes run from three to seven characters, and a decimal point follows the third character. Crucially, a three-character code is only billable when no further subdivision exists for it. Most three-character entries are category headers, and submitting one where subdivisions exist produces exactly the rejection above."},{type:"worked-example",title:"Building a complete fracture code",task:"Code a follow-up visit for a patient with a healing displaced fracture of the distal end of the left radius.",steps:[{move:"Start with the category: S52 covers fracture of the forearm.",why:"S-codes cover injuries by body region, and S52 narrows to the forearm. This is the category, not a billable code — building outward from the category is how you make sure you have not skipped a level of specificity."},{move:"Add characters for the specific site and fracture type.",why:"The distal radius has its own subdivision, and within it, codes separate displaced from non-displaced fractures. The documentation says displaced, so that branch is chosen. Where documentation does not specify, the coding guidelines direct that a fracture not indicated as displaced or non-displaced is coded as displaced."},{move:"Add laterality: left.",why:"The radius exists on both sides, so ICD-10-CM provides separate codes for right and left. The note documents left, so an unspecified-side code would be wrong and would likely be denied."},{move:"Add the 7th character for the encounter type.",why:"This is a follow-up during healing, so the extension for a subsequent encounter with routine healing applies — not the initial-encounter extension. The 7th character is what distinguishes the first visit for the injury from every visit afterwards, and choosing it wrongly changes the clinical meaning of the claim entirely."},{move:"Check the character count and insert the placeholder X if needed.",why:"The 7th character must sit in the 7th position. If the code has only five characters before it, X is inserted as a placeholder so the extension lands correctly. A 7th character in the wrong position produces an invalid code."}],result:"A complete, billable code specifying the bone, the site on that bone, the fracture type, the side, and the encounter type.",takeaway:"Build from the category outward and check every axis the code set offers — site, type, laterality, encounter. A code that stops short of available specificity is incomplete."}]},{heading:"The placeholder X and the 7th character",blocks:[{type:"paragraph",text:"Two features of ICD-10-CM confuse most newcomers, and both concern the tail of the code."},{type:"paragraph",text:"The placeholder X fills empty character positions so that a required 7th character lands in the 7th position. It carries no meaning of its own; it is purely positional. If a code needs a 7th character but only has four meaningful characters, X is inserted twice to pad positions five and six."},{type:"table",caption:"Common 7th character extensions for injuries",columns:["Extension","Means","Use for"],rows:[["A","Initial encounter","While the patient is receiving active treatment for the injury"],["D","Subsequent encounter","Routine care during the healing or recovery phase"],["S","Sequela","A complication or condition arising as a direct result of the injury"]]},{type:"callout",variant:"warning",text:"Initial encounter does not mean the first visit. It means the patient is receiving active treatment for the injury — which can span several visits, and can include a first visit to a new provider. Subsequent encounter means routine healing care. This is one of the most commonly miscoded elements in ICD-10-CM, precisely because the everyday meaning of 'initial' is not the coding meaning."},{type:"knowledge-check",question:"A patient is seen for the third time for a healing ankle fracture. No new treatment is provided; the provider checks healing progress. Which 7th character applies?",options:["A, because the fracture is still the reason for the visit","D, because this is routine care during the healing phase","S, because the fracture is an ongoing problem","No 7th character is needed for follow-up visits"],correctIndex:1,explanation:"D indicates a subsequent encounter — routine care while the injury heals, with no active treatment being provided. A would apply during active treatment, and S is reserved for a sequela, meaning a lasting condition resulting from the injury rather than the injury itself.",optionRationales:["A is for active treatment of the injury, not for monitoring healing progress.","Correct. Routine care during the healing phase is a subsequent encounter, extension D.","S is for a sequela — a late effect such as a resulting deformity — not for an injury that is still healing normally.","The 7th character is required for these injury codes at every encounter. Omitting it produces an invalid code."]}]}],challenge:[{type:"paragraph",text:"You will need access to a current ICD-10-CM code set. Free searchable versions are published by CMS."},{type:"list",ordered:!0,items:["Look up the category for type 2 diabetes mellitus. List three subdivisions that differ by complication, and note what documentation would be needed to choose between them.","Find a code that requires a 7th character and has fewer than six meaningful characters. Write it out with the placeholder X in the correct positions.","For a patient seen for a laceration of the right index finger without damage to the nail, find the most specific code available and note every axis of specificity you had to satisfy.","Explain in three sentences why a payer might deny an unspecified-laterality code even though the code is valid."]}]},{slug:"icd-10-cm-guidelines",title:"Using the Index, the Tabular List, and the Guidelines",description:"Learn the required two-step lookup process, and the conventions that determine which codes may be reported together and in what order.",duration:"24 min",objectives:["Use the Alphabetic Index and Tabular List in the correct order","Apply Excludes1 and Excludes2 notes correctly","Sequence a principal or first-listed diagnosis appropriately","Explain why signs and symptoms are not coded alongside a confirmed diagnosis"],sections:[{heading:"Never code from the index alone",blocks:[{type:"scenario",role:"You are coding under time pressure at Lakeside Medical Associates.",text:"You look up 'bronchitis' in the Alphabetic Index, find a code, and submit it. It is denied. Had you turned to that code in the Tabular List, you would have seen an instructional note requiring an additional code, and an Excludes1 note that ruled out the code you chose given the patient's documented condition.",task:"Build the two-step habit that the official guidelines require and that prevents this class of error entirely."},{type:"paragraph",text:"ICD-10-CM has two parts and both must be used. The Alphabetic Index is organized by condition and points you toward a code. The Tabular List is organized numerically and contains the actual code, along with the instructional notes that govern its use. The index never shows those notes, which is precisely why coding from it alone is unsafe."},{type:"paragraph",text:"The ICD-10-CM Official Guidelines for Coding and Reporting are published annually alongside the code set and are the authority for how codes are selected and sequenced. They are not optional guidance — HIPAA requires their use for reporting, and payers apply them."}]},{heading:"Excludes1 and Excludes2",blocks:[{type:"paragraph",text:"These two notes look almost identical and mean opposite things. Confusing them is one of the most consequential mistakes in diagnosis coding."},{type:"table",caption:"The two Excludes notes",columns:["Note","Means","Effect"],rows:[["Excludes1","NOT CODED HERE — the two conditions cannot occur together","Never report both codes for the same encounter"],["Excludes2","Not included here — the condition is separate but may coexist","Both codes may be reported together when both are documented"]]},{type:"paragraph",text:"The way to remember it: Excludes1 means mutually exclusive — one or the other, never both. Excludes2 means not part of this code, so if the patient has both conditions, code both. Payers apply Excludes1 edits automatically, so a claim carrying an Excludes1 pair is typically rejected without human review."},{type:"worked-example",title:"Deciding whether two codes may be reported together",task:"A patient is documented with two related conditions. The Tabular List entry for the first carries an Excludes2 note naming the second. May both be coded?",steps:[{move:"Identify which Excludes note applies.",why:"This is the whole decision, and it takes five seconds once you know to look. Excludes1 forbids reporting both; Excludes2 permits it. Reading the note carefully is the difference between a paid claim and a rejected one."},{move:"Confirm both conditions are documented independently.",why:"Excludes2 permits both codes; it does not require them. You still need documentation supporting each condition separately. Coding a second condition because the note allows it, without documentation, is unsupported coding."},{move:"Report both codes, sequencing by the reason for the encounter.",why:"The condition chiefly responsible for the visit is listed first. Sequence is not cosmetic — it drives medical necessity determinations and can affect payment and quality reporting."},{move:"If it had been Excludes1, choose the single code the documentation supports and query if genuinely ambiguous.",why:"Excludes1 means the code set asserts these cannot coexist. Reporting both is a definite rejection. When the documentation truly seems to describe both, that is a question for the provider rather than a coding judgment."}],result:"Both codes reported, correctly sequenced, each supported by documentation.",takeaway:"Excludes1 is mutually exclusive; Excludes2 permits coexistence. Always read the note in the Tabular List before reporting a pair of related codes."}]},{heading:"Sequencing and the signs-and-symptoms rule",blocks:[{type:"paragraph",text:"The first-listed diagnosis in the outpatient setting is the condition chiefly responsible for the services provided at that encounter. It is not necessarily the patient's most serious problem, and not necessarily the first one mentioned in the note."},{type:"paragraph",text:"The signs-and-symptoms rule follows from that. When a definitive diagnosis is established, code the diagnosis and not the symptoms that led to it — the symptoms are integral to it. When no definitive diagnosis is reached, code the symptoms, because that is what is actually known."},{type:"callout",variant:"warning",text:"In the outpatient setting, conditions documented as 'probable,' 'suspected,' 'rule out,' or 'questionable' are not coded as though they existed. Code the signs, symptoms, or test findings that prompted the workup instead. This differs from inpatient rules, where uncertain diagnoses documented at discharge may be coded as if established — a genuine difference between settings that catches people who move from one to the other."},{type:"knowledge-check",question:"A patient presents with chest pain. After evaluation the provider documents 'chest pain, rule out angina.' What should be coded?",options:["Angina, since that is the condition being investigated","Chest pain, because the angina is unconfirmed and this is an outpatient encounter","Both chest pain and angina, to capture the full picture","Neither, until the workup is complete"],correctIndex:1,explanation:"In the outpatient setting, a 'rule out' condition is not coded as though it were established. Code the documented symptom — chest pain — because that is what is actually known at this encounter. Coding the angina would assert a diagnosis the record does not support.",optionRationales:["Coding an unconfirmed condition in the outpatient setting asserts something the documentation explicitly does not establish.","Correct. Code the symptom; the suspected condition is not coded until it is confirmed.","Adding the unconfirmed diagnosis has the same problem on its own, and the symptom would in any case be integral to it were it confirmed.","The encounter happened and services were provided, so it must be coded. The symptom is the correct code."]}]}],challenge:[{type:"paragraph",text:"Work with the actual guidelines. CMS publishes the ICD-10-CM Official Guidelines for Coding and Reporting free each year."},{type:"list",ordered:!0,items:["Find one Excludes1 note and one Excludes2 note in the Tabular List. Write out each, and explain in your own words what a coder may and may not do in each case.","For an encounter documented as 'fatigue and weight loss, rule out malignancy,' decide what to code and write two sentences justifying it with reference to the guidelines.","A note documents both type 2 diabetes and diabetic neuropathy. Look up how the code set expects that relationship to be reported, and explain what a combination code is.","Describe the two-step lookup process in your own words, and state one specific thing you would miss by skipping the Tabular List."]}]}],level:"Intermediate",estimatedMinutes:48,whatYoullLearn:["The character structure of an ICD-10-CM code and what each position carries","The placeholder X and the 7th character extensions for injuries","Why the Alphabetic Index must always be confirmed in the Tabular List","Excludes1 versus Excludes2, sequencing, and the signs-and-symptoms rule"],scenario:"You submit S52.5 for a healing wrist fracture and the claim is rejected as an invalid code. Your reading of the chart was right; the code was a category header missing the characters that say which wrist, what kind of fracture, and which encounter this is. Learning the structure is what prevents that rejection."},{moduleNumber:4,moduleSlug:"module-4",title:"CPT & HCPCS Procedure Coding",emoji:"\uD83D\uDD22",description:"Code what the provider did: CPT structure and categories, office visit level selection under the current rules, and the modifiers that keep legitimate claims from being denied.",lessons:[{slug:"cpt-structure-and-categories",title:"CPT Structure and Categories",description:"Learn how procedure codes are organized, what the three CPT categories are for, and how to navigate the code set to find the right one.",duration:"24 min",objectives:["Describe the structure of CPT and its three categories","Navigate the CPT sections and use the index correctly","Explain what the CPT symbols and conventions signal","Distinguish CPT from HCPCS Level II and know when each applies"],sections:[{heading:"Codes for what was done",blocks:[{type:"scenario",role:"You code an office visit at Lakeside Medical Associates.",text:"The ICD-10-CM code says the patient has osteoarthritis of the left knee. That explains why care was needed. It says nothing about what the provider actually did — the examination, the joint injection, the X-ray. Without procedure codes, the claim describes a problem and requests payment for nothing in particular.",task:"Learn the code set that describes services delivered, and how it is organized."},{type:"paragraph",text:"CPT stands for Current Procedural Terminology. It is maintained by the American Medical Association, revised annually with changes effective 1 January, and it describes the services and procedures a provider performs. Every CPT code is five characters."},{type:"table",caption:"The three CPT categories",columns:["Category","Format","Purpose","Optional?"],rows:[["Category I","Five digits, e.g. 99213","Procedures and services in widespread use — the great majority of coding","No — these drive payment"],["Category II","Four digits plus F, e.g. 3006F","Performance measurement and quality reporting","Yes, but often required by quality programs"],["Category III","Four digits plus T, e.g. 0510T","Emerging technology, services, and procedures","No — use instead of an unlisted Category I code when one exists"]]},{type:"table",caption:"CPT Category I sections",columns:["Section","Range","Covers"],rows:[["Evaluation and Management","99202-99499","Office visits, consultations, hospital care"],["Anesthesia","00100-01999","Anesthesia services"],["Surgery","10004-69990","Surgical procedures by body system — the largest section"],["Radiology","70010-79999","Imaging and radiation oncology"],["Pathology and Laboratory","80047-89398","Lab tests and pathology"],["Medicine","90281-99607","Immunizations, cardiovascular studies, therapies"]]},{type:"callout",variant:"warning",text:"Never code directly from the CPT index. The index points you to a code or a range; the main text carries the full description, the parenthetical instructions, and the section guidelines that determine whether the code actually applies. This is the same two-step discipline ICD-10-CM requires, and skipping it produces the same class of error."},{type:"key-terms",terms:[{term:"HCPCS Level II",definition:"A separate code set — one letter plus four digits — for supplies, durable medical equipment, drugs, prosthetics, and ambulance services. Maintained by CMS."},{term:"Unlisted procedure code",definition:"A code used when no specific code describes the service. Requires a written report and is always manually reviewed, so it slows payment."},{term:"Bundled service",definition:"A service considered part of another and not separately payable. Reporting it separately is unbundling."},{term:"Global period",definition:"A window after a procedure during which related follow-up care is included in the original payment."}]},{type:"paragraph",text:"CPT covers physician services and procedures. HCPCS Level II covers what CPT does not — the wheelchair, the injectable drug, the surgical dressing, the ambulance transport. A single encounter can require both: a CPT code for administering an injection and a HCPCS Level II code for the drug that was injected."},{type:"knowledge-check",question:"A provider administers a therapeutic injection. Which code or codes are needed?",options:["A CPT code only, since the injection is a physician service","A CPT code for administering the injection and a HCPCS Level II code for the drug","A HCPCS Level II code only, since a drug was supplied","An ICD-10-CM code is sufficient, since it describes the condition treated"],correctIndex:1,explanation:"The administration is a service described by CPT; the drug itself is a supply described by HCPCS Level II. Reporting only one leaves the practice unpaid for the other, and this pairing is one of the most common places revenue is lost through incomplete coding.",optionRationales:["CPT covers the administration but has no code for the drug supplied, so the drug goes unbilled.","Correct. CPT for the service, HCPCS Level II for the drug.","HCPCS Level II covers the drug but not the professional work of administering it.","ICD-10-CM explains why care was needed. It never describes what was done and cannot support payment on its own."]}]}],challenge:[{type:"paragraph",text:"You will need access to a current CPT code set. Your program or library should provide one; the AMA publishes it annually."},{type:"list",ordered:!0,items:["Locate the six Category I sections in the code book and note the page each begins on. Read the guidelines at the start of the Surgery section.","Look up a routine office visit in the index, then find the code in the main text. List every piece of information the main text gives you that the index did not.","Find one Category III code and explain in two sentences why it exists rather than a Category I code.","For a patient receiving an injectable medication, identify what you would need from the documentation to code both the administration and the drug."]}]},{slug:"evaluation-and-management-coding",title:"Evaluation and Management Coding",description:"Code office visits under the current rules, which are based on medical decision making or total time rather than the old history-and-exam bullet counts.",duration:"26 min",objectives:["Explain what E/M codes describe and why they are high volume","Select an office visit level using medical decision making","Select a level using total time on the date of the encounter","Distinguish new from established patients"],sections:[{heading:"The most-billed codes in outpatient medicine",blocks:[{type:"scenario",role:"You code a primary care day at Lakeside Medical Associates.",text:"Twenty-two of the day's twenty-four encounters are office visits. Each needs a level assigned — and the level determines payment, so a practice that systematically codes one level too low leaves substantial revenue uncollected, while one that codes too high is submitting false claims.",task:"Learn to select an office visit level from what the documentation actually supports."},{type:"paragraph",text:"Evaluation and Management codes describe cognitive work: the assessment, the decision making, the counseling. They are the highest-volume codes in outpatient medicine and the most scrutinized, because level selection has historically been inconsistent."},{type:"callout",variant:"info",text:"Office visit E/M coding changed substantially in 2021. The old system counted history and examination bullets to arrive at a level. Those elements must still be medically appropriate and documented, but they no longer determine the level. Level is now selected by either medical decision making or total time on the date of the encounter — the coder's choice, whichever supports the higher level. Older training material still teaches the bullet-counting method; it does not apply to office visits."},{type:"table",caption:"Office visit code families",columns:["Patient type","Codes","Definition"],rows:[["New patient","99202-99205","Has not received professional services from the provider, or another of the same specialty in the same group, within three years"],["Established patient","99211-99215","Has received such services within three years"]]},{type:"paragraph",text:"The three-year rule matters financially: new patient visits pay more, because more work is involved in an initial assessment. It turns on the same specialty and same group practice, not merely the same individual provider — a patient seen by a different physician in your practice's same specialty within three years is established."},{type:"table",caption:"The three elements of medical decision making",columns:["Element","Considers"],rows:[["Number and complexity of problems addressed","How many problems, and how serious or unstable"],["Amount and complexity of data reviewed","Tests ordered or reviewed, records obtained, discussion with other providers"],["Risk of complications or morbidity","Risk from the problems, the diagnostic testing, and the treatment chosen"]]},{type:"paragraph",text:"Two of the three elements must be met or exceeded at a given level to support it. The levels run straightforward, low, moderate, and high, corresponding to codes 99202/99212 through 99205/99215."},{type:"worked-example",title:"Selecting a level two ways",task:"An established patient is seen for two chronic conditions, one uncontrolled. The provider reviews recent labs, adjusts a prescription, and documents 40 minutes total on the date of the encounter.",steps:[{move:"Try medical decision making first.",why:"Two chronic conditions with one uncontrolled generally supports moderate complexity on the problems element. Reviewing labs contributes to the data element. Prescription drug management is a recognized moderate-risk item. Two of three at moderate supports 99214."},{move:"Then check total time as an alternative.",why:"Time is the other permitted route, and you may use whichever supports the higher level. Total time includes the provider's non-face-to-face work on that date — reviewing records beforehand, documenting afterwards — not only the time in the room."},{move:"Compare 40 minutes against the time thresholds for established patient visits.",why:"40 minutes falls in the range for 99215 rather than 99214. Here time supports a higher level than medical decision making does, so time is the better basis — provided the total time is actually documented."},{move:"Confirm the documentation states total time explicitly.",why:"This is where time-based selection fails. A note saying '40 minutes spent, including review of labs and counseling on medication changes' supports it. A note with no time statement cannot support time-based selection at all, no matter how long the visit actually took."}],result:"99215, supported by documented total time, with medical decision making independently supporting at least 99214.",takeaway:"Check both routes and use whichever the documentation supports at the higher level. Time-based selection requires the total time to be stated in the note."},{type:"callout",variant:"warning",text:"A consistent pattern of coding the same level for every visit — whether that is always 99213 or always 99214 — attracts payer attention regardless of which level it is. Real patient panels produce a distribution across levels. Coding defensively low is not a safe strategy; it is a different pattern anomaly, and it costs the practice revenue it legitimately earned."},{type:"knowledge-check",question:"A patient last seen by a different physician of the same specialty in your practice two years ago returns. Which code family applies?",options:["New patient, because this is a different physician","Established patient, because the same specialty in the same group saw them within three years","New patient, because more than one year has passed","Either may be used, at the coder's discretion"],correctIndex:1,explanation:"The rule turns on the same specialty within the same group practice, not the individual provider. Two years is inside the three-year window, so this is an established patient — and coding it as new would be upcoding, since new patient visits pay more.",optionRationales:["The rule covers the group and specialty, not just the individual physician.","Correct. Same specialty, same group, within three years means established.","The window is three years, not one.","There is no discretion. The three-year rule determines it."]}]}],challenge:[{type:"paragraph",text:"Practice level selection against real documentation standards. Use the current CPT E/M guidelines."},{type:"list",ordered:!0,items:["Read the E/M guidelines at the front of the CPT Evaluation and Management section. Write down the time thresholds for 99212 through 99215.","For an established patient with one stable chronic condition, no tests ordered, and no prescription change, determine the supportable level using medical decision making and justify it.","For the same encounter documented as 30 minutes total time, determine the level using time. Explain which basis you would use and why.","Write three sentences a provider could add to a note that would support time-based selection, and explain what makes them sufficient."]}]},{slug:"modifiers",title:"Modifiers",description:"Use two-character modifiers to tell a payer that something about a service was different from the default assumption.",duration:"22 min",objectives:["Explain what a modifier does and why claims are denied without one","Apply the most common modifiers correctly","Distinguish modifier 25 from modifier 59","Recognize when modifier use crosses into abuse"],sections:[{heading:"A modifier answers an objection before it is raised",blocks:[{type:"scenario",role:"You code an encounter at Lakeside Medical Associates.",text:"A patient comes in for a scheduled joint injection. During the visit they raise a new, unrelated complaint, and the provider evaluates it. You bill the injection and an office visit. The payer denies the office visit as bundled into the procedure — because by default it assumes any visit on the day of a procedure is part of that procedure.",task:"Learn the modifiers that tell a payer the default assumption does not apply here."},{type:"paragraph",text:"A modifier is a two-character code appended to a CPT or HCPCS code. It does not change what the code means; it adds a fact about the circumstances — that the service was distinct, that it was on the left side, that it was reduced, that a different provider performed it."},{type:"table",caption:"Frequently used modifiers",columns:["Modifier","Means","Typical use"],rows:[["25","Significant, separately identifiable E/M service on the same day as a procedure","A patient seen for one thing who is also evaluated for something else"],["59","Distinct procedural service","Two procedures normally bundled that were genuinely separate here"],["LT / RT","Left side / right side","Procedures on paired structures"],["50","Bilateral procedure","The same procedure on both sides"],["76","Repeat procedure by the same provider","A second X-ray the same day"],["91","Repeat clinical diagnostic laboratory test","A repeated lab test for a clinical reason"],["GA","Waiver of liability on file (ABN signed)","Medicare may not cover; the patient was notified"]]},{type:"paragraph",text:"Modifier 25 and modifier 59 are the two most misused codes in the entire field, and both are routinely audited. The distinction is worth stating precisely: modifier 25 applies to an evaluation and management service performed alongside a procedure. Modifier 59 applies to a procedure performed alongside another procedure."},{type:"callout",variant:"warning",text:"Modifier 59 in particular is an audit flag. It overrides a National Correct Coding Initiative edit — a payer rule saying two codes should not normally be billed together — so appending it asserts that this case is a genuine exception. Where a more specific modifier exists (XE, XS, XP, XU), use it instead. Never append 59 simply to get a denied claim paid; doing so knowingly is unbundling, which is fraud rather than an aggressive coding choice."},{type:"worked-example",title:"Deciding whether modifier 25 applies",task:"A patient attends for a scheduled joint injection and also raises a new, unrelated complaint that the provider evaluates.",steps:[{move:"Ask whether the E/M work was significant and separately identifiable.",why:"This is the actual test. Every procedure includes some evaluation — assessing the site, confirming the plan. Modifier 25 is for work beyond that, addressing a different issue. Routine pre-procedure assessment never qualifies."},{move:"Check the documentation supports a distinct evaluation.",why:"There must be a separately documented history, assessment, and plan for the other complaint. If the note describes only the injection, the E/M is not supportable regardless of what happened in the room — and the fix is a provider query, not a modifier."},{move:"Append modifier 25 to the E/M code, not to the procedure.",why:"This trips people constantly. The modifier goes on the code it describes, and modifier 25 describes the E/M service. Appending it to the injection code is simply wrong and will be rejected."},{move:"Confirm a different diagnosis supports the E/M where possible.",why:"A separate diagnosis code linked to the E/M makes the separate identifiability visible to the payer on the face of the claim. It is not strictly required, but it substantially reduces the chance of a denial you then have to appeal."}],result:"The injection and the office visit both paid, with the E/M carrying modifier 25 and its own supporting diagnosis.",takeaway:"Modifier 25 attaches to the E/M, and only when the evaluation went genuinely beyond the procedure's inherent assessment."},{type:"knowledge-check",question:"A provider performs a scheduled procedure and, at the same visit, evaluates a separate new complaint. Which modifier applies, and to which code?",options:["Modifier 59, appended to the procedure code","Modifier 25, appended to the E/M code","Modifier 25, appended to the procedure code","No modifier — the visit is included in the procedure"],correctIndex:1,explanation:"Modifier 25 identifies a significant, separately identifiable E/M service on the same day as a procedure, and it attaches to the E/M code it describes. Modifier 59 applies between two procedures, not between a procedure and an E/M service.",optionRationales:["Modifier 59 distinguishes one procedure from another. There is only one procedure here.","Correct. Modifier 25 goes on the E/M code.","The modifier attaches to the code it describes, which is the E/M service, not the procedure.","Evaluating a separate new complaint is exactly what modifier 25 exists for. Omitting it forfeits legitimate payment."]}]}],challenge:[{type:"paragraph",text:"Modifiers reward precision. Work from the CPT modifier appendix."},{type:"list",ordered:!0,items:["Find the modifier appendix in your CPT book and read the full descriptions of modifiers 25, 59, 50, and 76.","Research the X modifiers (XE, XS, XP, XU) and explain in three sentences why CMS introduced them as alternatives to 59.","For a bilateral procedure, determine whether your payer prefers modifier 50 or LT and RT on separate lines. Note where you found the answer.","Write a short guidance note for a colleague on when modifier 25 is and is not appropriate, using the injection scenario as the example."]}]}],level:"Intermediate",estimatedMinutes:72,whatYoullLearn:["CPT structure, its three categories, and how it differs from HCPCS Level II","Selecting an office visit level by medical decision making or by total time","The new versus established patient rule and why it affects payment","Modifiers 25 and 59, the two most misused codes in the field"],scenario:"The diagnosis code says the patient has osteoarthritis of the left knee. That explains why care was needed and says nothing about what the provider did — the examination, the injection, the X-ray. Twenty-two of the day's twenty-four encounters are office visits, and each needs a level that the documentation actually supports."},{moduleNumber:5,moduleSlug:"module-5",title:"Payers, Eligibility & Authorization",emoji:"\uD83D\uDEE1️",description:"Do the front-end work that prevents most denials, and understand how payers decide what to pay.",lessons:[{slug:"eligibility-and-authorization",title:"Eligibility Verification and Prior Authorization",description:"Do the front-end work that prevents most denials, and understand the difference between coverage, authorization, and medical necessity.",duration:"24 min",objectives:["Verify eligibility and interpret what a verification actually confirms","Explain when prior authorization is required and how to obtain it","Distinguish coverage, authorization, and medical necessity","Use an ABN correctly for Medicare patients"],sections:[{heading:"The cheapest denial is the one never generated",blocks:[{type:"scenario",role:"You work the front desk at Lakeside Medical Associates.",text:"In Module 1 you found that 112 of last month's 138 denials originated before the patient was ever seen — eligibility, authorization, and missing information. Every one of those was preventable in the ninety seconds before the appointment, and each now costs far more to work than it would have cost to prevent.",task:"Learn the front-end checks that stop denials being generated at all."},{type:"paragraph",text:"Eligibility verification confirms that the patient's coverage is active on the date of service and that your practice is in network. It is done electronically in seconds through a clearinghouse or payer portal, and it should happen twice: at scheduling, and again at check-in, because coverage changes between the two."},{type:"table",caption:"What to verify, and why each matters",columns:["Check","Confirms","Denial it prevents"],rows:[["Policy active on the date of service","Coverage has not lapsed","Coverage terminated"],["Member ID and group number","The claim will route correctly","Invalid subscriber information"],["In-network status","Contracted rates apply","Out-of-network reduction or denial"],["Copay, deductible, coinsurance","What to collect at the desk","Uncollected patient balance"],["Prior authorization requirements","Whether approval is needed first","No authorization on file"],["Referral requirements","Whether a referral is needed","No referral on file"]]},{type:"paragraph",text:"Three things are commonly conflated and are genuinely different. Coverage means the plan includes this benefit. Authorization means the payer has approved this specific service in advance. Medical necessity means the service was appropriate for the patient's documented condition. A service can be covered, authorized, and still denied for medical necessity if the documentation does not support it."},{type:"callout",variant:"warning",text:"An eligibility verification is not a guarantee of payment, and payers say so explicitly in their responses. It confirms coverage was active when you checked. The claim can still be denied for medical necessity, for a non-covered service, or because the patient's deductible absorbed the payment. Verification reduces risk substantially; it does not eliminate it, and telling a patient 'your insurance will cover this' overstates what you actually know."},{type:"worked-example",title:"Handling a service Medicare may not cover",task:"A Medicare patient is scheduled for a service you believe Medicare will consider not reasonable and necessary.",steps:[{move:"Confirm the likely non-coverage before the service, not after.",why:"Check the applicable coverage determination. Discovering non-coverage after delivery means the practice either absorbs the cost or bills a patient who was never warned — and the second option is where complaints come from."},{move:"Issue an Advance Beneficiary Notice of Noncoverage and have the patient sign it.",why:"The ABN is a specific CMS form telling the patient Medicare may not pay and that they may be responsible. Without it, you generally cannot bill the patient when Medicare denies. It must be given before the service and must state a genuine reason."},{move:"Append modifier GA to the claim line.",why:"GA tells Medicare a signed waiver is on file. It is what preserves the practice's ability to bill the patient after the denial, and omitting it means the denial lands on the practice."},{move:"Never issue blanket ABNs routinely to every patient.",why:"Routine ABNs issued without a specific expectation of non-coverage are invalid, and CMS treats the practice as one. The form exists to inform a patient about a particular service, not to shift all risk onto patients as a matter of policy."}],result:"The patient is informed before the service, and the practice retains the right to bill them if Medicare denies.",takeaway:"The ABN protects the patient's right to decide and the practice's right to bill. It only works when it is specific, signed in advance, and flagged with modifier GA."},{type:"knowledge-check",question:"You verify eligibility and the payer confirms active coverage. The claim is later denied for medical necessity. What went wrong?",options:["The eligibility verification was performed incorrectly","Nothing about the verification — eligibility confirms coverage, not that a specific service was appropriate for the documented condition","The payer is obligated to pay, since coverage was confirmed","Prior authorization was obtained but not recorded"],correctIndex:1,explanation:"Eligibility, authorization, and medical necessity are three separate determinations. Confirming coverage was active says nothing about whether the documentation supports this particular service for this patient's condition. The next step is to review the documentation and consider an appeal.",optionRationales:["The verification did what it does. It was never a medical necessity determination.","Correct. Coverage, authorization, and medical necessity are separate questions.","Payer responses explicitly state that verification is not a guarantee of payment.","Authorization is also separate from medical necessity — an authorized service can still be denied on necessity grounds."]}]}],challenge:[{type:"paragraph",text:"Build the front-end process that prevents the denials you costed in Module 1."},{type:"list",ordered:!0,items:["Write a front-desk verification checklist covering every item in the table above, formatted so someone could work through it in ninety seconds.","Research the CMS ABN form (CMS-R-131). Note the three things the form must state to be valid.","Explain in three sentences the difference between coverage, authorization, and medical necessity, using an example of a service that could fail each one.","Given 61 eligibility denials and 29 authorization denials last month, write a two-paragraph recommendation to the practice manager naming what you would change and how you would measure it."]}]},{slug:"payer-rules-and-fee-schedules",title:"Payer Rules and Fee Schedules",description:"Understand how payers decide what to pay, and why the same service produces different payments from different plans.",duration:"22 min",objectives:["Explain what a fee schedule is and how allowed amounts are set","Describe how Medicare's RBRVS system works at a practical level","Explain timely filing limits and why they are absolute","Read a payer contract for the terms that affect billing"],sections:[{heading:"The contract sets the price",blocks:[{type:"scenario",role:"You reconcile payments at Lakeside Medical Associates.",text:"The same office visit code produces $186 from one payer, $142 from another, and $109 from Medicaid. Nothing about the encounters differed. Three contracts set three prices, and the practice agreed to all three.",task:"Understand where allowed amounts come from, so you can tell an underpayment from a contracted rate."},{type:"paragraph",text:"A fee schedule is the list of allowed amounts a payer will pay for each code. In-network providers agree to accept it as payment in full and write off the difference from their charge. This is why the billed amount is largely a starting figure — the contract, not the charge, determines the money."},{type:"paragraph",text:"Medicare sets its fee schedule using the Resource-Based Relative Value Scale. Each code carries relative value units reflecting physician work, practice expense, and malpractice risk. Those are adjusted geographically and multiplied by a national conversion factor to produce a dollar amount. Many commercial payers set their rates as a percentage of Medicare, which is why Medicare's annual changes ripple across the whole payer mix."},{type:"callout",variant:"warning",text:"Timely filing limits are absolute and unforgiving. A payer may allow 90 days from the date of service, or 180, or a year — but past that deadline the claim is denied and generally cannot be appealed on any grounds, because the failure was the practice's. A clean claim worth $1,200 that sits unworked for four months is worth nothing. This is why aged accounts receivable matters so much: old claims are not just harder to collect, some become uncollectible by rule."},{type:"table",caption:"Contract terms that affect daily billing",columns:["Term","Why it matters"],rows:[["Fee schedule","The allowed amount for every code you bill"],["Timely filing limit","The deadline past which a claim cannot be paid"],["Appeal window and levels","How long you have to dispute, and how many attempts"],["Authorization requirements","Which services need approval in advance"],["Clean claim definition","What the payer must receive before its payment clock starts"],["Payment turnaround","When you can reasonably begin following up"]]},{type:"knowledge-check",question:"A clean, correctly coded claim for $1,200 is discovered unworked four months after the date of service. The payer's timely filing limit is 90 days. What is the realistic outcome?",options:["It will be paid, since the claim itself is correct","It will be denied for untimely filing, and generally cannot be appealed because the delay was the practice's","It can be resubmitted with a corrected date of service","The patient becomes responsible for the full amount"],correctIndex:1,explanation:"Timely filing is a contractual deadline, not a quality judgment about the claim. Past it the payer owes nothing, and appeals on grounds of practice delay do not succeed. This is why unworked claims aging in accounts receivable represent permanent revenue loss rather than delayed revenue.",optionRationales:["Correctness does not matter once the filing deadline has passed.","Correct. The claim is denied as untimely, and the practice absorbs the loss.","Altering the date of service to defeat a filing limit is falsification of a claim — a serious offence, not a workaround.","The patient is not responsible for the practice's failure to file on time, and billing them for it is generally prohibited by the payer contract."]}]}],challenge:[{type:"paragraph",text:"Work with real numbers and real contract terms."},{type:"list",ordered:!0,items:["Find the current Medicare Physician Fee Schedule lookup tool on the CMS website. Look up the allowed amount for a common office visit code in your locality.","Explain in three sentences how RVUs and the conversion factor produce that dollar amount.","Research typical timely filing limits for three payer types. Note the range and where you found each.","Design a simple weekly report a biller could run to catch claims approaching a filing deadline, and say what it would need to show."]}]}],level:"Intermediate",estimatedMinutes:46,whatYoullLearn:["What an eligibility verification confirms, and what it does not","The difference between coverage, authorization, and medical necessity","Using an ABN and modifier GA for Medicare services that may not be covered","Fee schedules, RBRVS, and why timely filing limits are absolute"],scenario:"In Module 1 you found that 112 of last month's 138 denials originated before the patient was ever seen. Every one was preventable in the ninety seconds before the appointment. Meanwhile the same office visit code pays $186 from one payer, $142 from another, and $109 from Medicaid."},{moduleNumber:6,moduleSlug:"module-6",title:"Claim Submission",emoji:"\uD83D\uDCE4",description:"Build a clean claim, understand the fields that cause rejections, and follow it through adjudication to a correctly posted payment.",lessons:[{slug:"the-cms-1500-and-claim-fields",title:"The CMS-1500 and What Each Field Carries",description:"Understand the professional claim form, the electronic transaction behind it, and the fields that most often cause rejections.",duration:"24 min",objectives:["Describe the CMS-1500 and its electronic equivalent","Identify the fields that most commonly cause rejections","Distinguish a rejection from a denial","Explain what a clean claim is"],sections:[{heading:"One form, and the transaction behind it",blocks:[{type:"scenario",role:"You submit claims at Lakeside Medical Associates.",text:"Twelve claims come back the same afternoon, before any payer looked at them clinically. They were rejected by the clearinghouse for invalid subscriber ID, missing NPI, and a diagnosis pointer referencing a diagnosis that was not on the claim. None of these are coding problems. All twelve were preventable.",task:"Learn what the claim actually carries, so the fields that reject are the ones you check first."},{type:"paragraph",text:"The CMS-1500 is the standard claim form for professional services — physician and outpatient practice billing. Institutional claims from hospitals use the UB-04, also called the CMS-1450. Almost all claims are transmitted electronically rather than on paper: the CMS-1500 corresponds to the 837P transaction, and the UB-04 to the 837I."},{type:"paragraph",text:"Even when you never see the paper form, its field structure is what the electronic transaction carries and what every billing system's screens are modeled on. Knowing the fields is knowing the claim."},{type:"table",caption:"Fields that most often cause rejections",columns:["Field","Carries","Common failure"],rows:[["Subscriber ID","The member number exactly as issued","Transposed digits, or the wrong plan's format"],["Patient name and date of birth","Must match payer records exactly","Nickname instead of legal name; wrong DOB"],["Insured's relationship to patient","Self, spouse, child","Defaulting to self for a dependent"],["Diagnosis codes","Up to twelve ICD-10-CM codes","Invalid code, or one lacking required specificity"],["Diagnosis pointer","Links each service line to its diagnosis","Pointing at a diagnosis not present on the claim"],["Rendering provider NPI","Who performed the service","Missing, or the group NPI where an individual is required"],["Place of service code","Where the service occurred","Office code used for a telehealth encounter"],["Prior authorization number","The approval reference","Obtained but never entered"]]},{type:"key-terms",terms:[{term:"Rejection",definition:"The claim failed a format or data check and never entered adjudication. It is corrected and resubmitted as a new claim — not appealed."},{term:"Denial",definition:"The claim was adjudicated and the payer decided not to pay. This is appealed, not resubmitted."},{term:"Clean claim",definition:"A claim with no defects requiring the payer to seek more information. It starts the payer's payment clock."},{term:"Clearinghouse",definition:"An intermediary that validates claims against payer rules and routes them. Its edits catch problems before the payer sees them."},{term:"NPI",definition:"National Provider Identifier — a ten-digit number identifying a provider. Both the individual and the group have one."}]},{type:"callout",variant:"info",text:"The rejection-versus-denial distinction determines what you do next, and getting it wrong wastes weeks. A rejection never reached adjudication, so there is no decision to appeal — you fix the data and resubmit. A denial is a decision, so resubmitting the same claim gets the same denial; it must be appealed or corrected as a corrected claim. Billers who appeal rejections and resubmit denials generate a great deal of work and very little payment."},{type:"knowledge-check",question:"A claim comes back from the clearinghouse the same day, flagged for an invalid subscriber ID. What is the correct next step?",options:["File an appeal, since the payer refused the claim","Correct the subscriber ID and resubmit — this is a rejection, which never reached adjudication","Bill the patient, since insurance declined","Write it off as uncollectible"],correctIndex:1,explanation:"A same-day clearinghouse rejection means the claim failed a data check and never reached the payer's adjudication system. There is no decision to appeal. Correct the identifier and resubmit it as a new claim.",optionRationales:["There is nothing to appeal — no payer decision was ever made.","Correct. Fix the data and resubmit; this is a rejection, not a denial.","Insurance did not decline anything. The claim never reached them.","The claim is entirely collectible once the identifier is corrected."]}]}],challenge:[{type:"paragraph",text:"Work from the actual form. CMS publishes the CMS-1500 and its instructions free."},{type:"list",ordered:!0,items:["Download a blank CMS-1500 and the NUCC instruction manual. Identify the box number for each field in the table above.","Complete a CMS-1500 by hand for a straightforward office visit using invented, non-real patient details.","Explain in three sentences the difference between a rejection and a denial, and what you would do differently for each.","List five items you would build into a pre-submission checklist, chosen to catch the most common rejections."]}]},{slug:"claim-scrubbing-and-submission",title:"Claim Scrubbing and Submission",description:"Catch errors before a claim leaves the practice, and understand the path a claim takes from submission to payment.",duration:"22 min",objectives:["Explain what claim scrubbing does and why it pays for itself","Describe the path from submission through adjudication to remittance","Read an explanation of benefits and an electronic remittance advice","Post payments and adjustments correctly"],sections:[{heading:"Catch it before it leaves",blocks:[{type:"scenario",role:"You run the billing cycle at Lakeside Medical Associates.",text:"A claim rejected by the clearinghouse costs a few minutes to fix. The same error caught after the payer denies it costs weeks of turnaround and a follow-up call, and may push the claim toward its filing deadline. The error is identical; only when it was caught differs.",task:"Understand scrubbing well enough to make the first-pass rate the number you manage."},{type:"paragraph",text:"Claim scrubbing runs claims against a rules engine before submission — checking code validity, required modifiers, diagnosis-to-procedure linkage, NCCI edits, and payer-specific requirements. Every error it catches is an error that never becomes a denial."},{type:"table",caption:"The claim's journey",columns:["Stage","What happens","Typical timing"],rows:[["Charge entry","Codes and charges entered","Day of service or next day"],["Scrubbing","Rules engine checks the claim","Immediate"],["Submission","Transmitted to the clearinghouse","Daily batch"],["Clearinghouse edits","Format and payer-rule validation","Same day"],["Payer receipt","Acknowledgement returned","1-2 days"],["Adjudication","Payer decides what to pay","7-30 days"],["Remittance","Payment and explanation returned","With payment"],["Posting","Payment and adjustments recorded","On receipt"]]},{type:"paragraph",text:"The payer returns its decision as an explanation of benefits, or electronically as an 835 remittance advice. It shows, per service line, the billed amount, the allowed amount, the contractual adjustment, what the plan paid, and what the patient owes — along with reason codes explaining any reduction."},{type:"worked-example",title:"Posting a remittance correctly",task:"Post a line showing billed $340, allowed $186, plan paid $148.80, patient responsibility $37.20.",steps:[{move:"Post the payment of $148.80 against the claim.",why:"The actual money received. Straightforward, and the part everyone gets right."},{move:"Post the $154 difference as a contractual adjustment.",why:"Billed minus allowed. This is written off under the payer contract and may never be billed to the patient — posting it as anything else, or leaving it as an open balance, misstates the practice's receivables and risks an improper patient bill."},{move:"Move the $37.20 to patient responsibility.",why:"The coinsurance or deductible portion becomes the patient's balance and enters the patient billing cycle. Leaving it against insurance means it is never billed to anyone."},{move:"Read the reason codes even when the line paid as expected.",why:"Reason codes explain reductions and often flag a pattern — a modifier consistently missing, a code repeatedly bundled. Posting mechanically without reading them means you fix individual claims and never the cause producing them."}],result:"The account balances to zero against insurance, with $37.20 correctly owed by the patient.",takeaway:"Payment, contractual adjustment, patient responsibility. Read the reason codes — they are where the recurring problems announce themselves."},{type:"knowledge-check",question:"Why is a claim error caught by a scrubber far cheaper than the same error caught by the payer?",options:["Scrubbers charge less per claim than payers do","The scrubbed claim is corrected in minutes and still submits on time, while a payer denial costs weeks of turnaround and consumes filing-limit time","Payers charge a penalty for denied claims","Scrubbed claims are paid at a higher rate"],correctIndex:1,explanation:"The error is identical; the cost is entirely in when it is caught. A scrubber rejection is fixed the same day. A payer denial arrives weeks later, requires rework and follow-up, and consumes time against the timely filing limit — occasionally enough that the claim becomes uncollectible.",optionRationales:["Payers do not charge per claim. The cost is staff time and delay.","Correct. The difference is turnaround time and filing-limit exposure.","Payers do not levy penalties for denials.","The allowed amount comes from the contract and does not change based on how cleanly the claim arrived."]}]}],challenge:[{type:"paragraph",text:"Practice reading a remittance, which is most of a biller's daily work."},{type:"list",ordered:!0,items:["Find a sample explanation of benefits online. Identify the billed amount, allowed amount, contractual adjustment, plan payment, and patient responsibility for one line.","Research CARC and RARC codes. Explain what each set is for and find three examples of each.","For a line showing billed $500, allowed $300, paid $240, calculate the contractual adjustment and the patient responsibility, and state what percentage coinsurance that implies.","Describe a weekly routine for reviewing reason codes across all remittances, and say what you would be looking for."]}]}],level:"Intermediate",estimatedMinutes:46,whatYoullLearn:["The CMS-1500, the 837P transaction, and the fields that most often reject","The difference between a rejection and a denial, and why it changes what you do","What claim scrubbing catches and why it pays for itself","Reading a remittance and posting payment, adjustment, and patient responsibility"],scenario:"Twelve claims come back the same afternoon, before any payer looked at them clinically — invalid subscriber ID, missing NPI, a diagnosis pointer referencing a diagnosis not on the claim. None are coding problems. All twelve were preventable."},{moduleNumber:7,moduleSlug:"module-7",title:"Denials, Appeals & A/R",emoji:"\uD83D\uDCCA",description:"Work a denial queue by deadline and recoverable value, write appeals that succeed, and manage accounts receivable before claims age into worthlessness.",lessons:[{slug:"working-denials",title:"Working Denials",description:"Read a denial, identify its real cause, and decide between correcting, appealing, and writing it off.",duration:"26 min",objectives:["Interpret denial reason codes","Categorize denials by root cause and by whether they are preventable","Choose between a corrected claim, an appeal, and a write-off","Prioritize a denial queue by recoverable value"],sections:[{heading:"A denial is information about a process",blocks:[{type:"scenario",role:"You inherit the denial queue at Lakeside Medical Associates.",text:"There are 138 denials worth $47,000. Working them oldest-first would be reasonable if they were equivalent. They are not: some are worth $40 and some $3,000, some are five days from a filing deadline, and roughly a third are eligibility denials with no realistic prospect of recovery.",task:"Work the queue by recoverable value and deadline rather than by date order."},{type:"paragraph",text:"Every denial carries reason codes. Claim Adjustment Reason Codes state why the amount was reduced; Remittance Advice Remark Codes add detail. Reading them is the first step, and the code frequently names the fix directly."},{type:"table",caption:"Common denial categories and what to do",columns:["Category","Usually means","Action"],rows:[["Eligibility / coverage terminated","Coverage was not active on the date of service","Check for other coverage; often becomes patient responsibility. Rarely appealable"],["No prior authorization","Required approval was not obtained","Request retroactive authorization if the payer permits; appeal with clinical justification"],["Medical necessity","Documentation does not support the service","Appeal with records if the documentation does support it; otherwise the denial stands"],["Bundling / NCCI edit","Two codes should not be billed together","Review whether a modifier is genuinely warranted. Do not add one reflexively"],["Duplicate claim","Payer already has this claim","Check status before resubmitting — usually the original is still processing"],["Timely filing","Submitted past the deadline","Generally not recoverable. Investigate why it aged"],["Non-covered service","The plan excludes this benefit","Bill the patient if an ABN or equivalent notice is on file"]]},{type:"worked-example",title:"Prioritizing a 138-claim denial queue",task:"Decide the order to work $47,000 of denials with limited staff time.",steps:[{move:"Sort by days remaining until the appeal or filing deadline.",why:"Deadlines are absolute. A $3,000 claim five days from its appeal window is worth more attention today than a $3,000 claim with ninety days left, because one becomes worthless on a known date and the other does not."},{move:"Within that, sort by dollar value.",why:"Staff time is the constraint. Ten minutes recovering $2,400 is a better use of it than ten minutes recovering $40 — and the small-dollar denials are usually the ones a practice should be preventing rather than working."},{move:"Set aside the categories with no realistic recovery.",why:"Eligibility denials where coverage genuinely was not active, and timely filing denials caused by the practice, will not be paid. Working them feels productive and recovers nothing. Route them to patient billing or write-off and spend the time where recovery is possible."},{move:"Group the remainder by reason code and look for patterns.",why:"Twenty-nine authorization denials are not twenty-nine problems; they are one process problem twenty-nine times. Fixing the front-end process stops the thirtieth, which is worth more than recovering any single claim."},{move:"Report the pattern, not just the recovery total.",why:"'We recovered $18,000' is an outcome. 'We recovered $18,000, and 29 denials came from one gap in the authorization process that I have proposed fixing' is an outcome plus a prevention — and the second is what changes next month's numbers."}],result:"Deadline-critical high-value claims worked first, unrecoverable categories routed appropriately, and the root cause identified.",takeaway:"Work by deadline and value, not by date received. Then look for the pattern — denials are a symptom of a process, and the process is where the leverage is."},{type:"callout",variant:"warning",text:"Never resubmit an identical claim in response to a denial. The payer has already adjudicated it and will return the same decision, or reject it as a duplicate — while the appeal window continues to run. A denial requires a corrected claim, marked as such, or a formal appeal. Resubmitting is the most common way a recoverable denial becomes unrecoverable."},{type:"knowledge-check",question:"You have 138 denials of varying value and deadline. What should determine the order you work them?",options:["Oldest first, so nothing sits too long","Deadline proximity first, then dollar value, setting aside categories with no realistic recovery","Smallest first, to reduce the claim count quickly","Alphabetically by payer, to batch phone calls"],correctIndex:1,explanation:"Deadlines are absolute — a claim past its appeal window is worth nothing regardless of value. Within that constraint, dollar value determines where limited staff time returns the most. Categories that cannot realistically be recovered should be routed rather than worked.",optionRationales:["Age correlates loosely with deadline but ignores value entirely, and some old denials are already unrecoverable.","Correct. Deadline, then value, with unrecoverable categories set aside.","Reducing the count feels productive but leaves the largest recoverable balances at risk.","Batching calls by payer helps efficiency but should operate within a deadline-and-value ordering, not replace it."]}]}],challenge:[{type:"paragraph",text:"Practice triage, which is most of what denial work actually is."},{type:"list",ordered:!0,items:["Research CARC and RARC code sets. Find the codes for medical necessity, no authorization, and timely filing.","Given these denials — $2,400 medical necessity with 8 days left to appeal; $180 eligibility with 60 days; $3,100 no authorization with 45 days; $95 timely filing — rank them and justify each position.","Write an appeal letter for the medical necessity denial. State the claim, the denial reason, why the documentation supports the service, and what you are asking for.","For the same month's denial mix, name the single process change you would recommend and estimate what it would prevent."]}]},{slug:"appeals-and-accounts-receivable",title:"Appeals and Accounts Receivable Follow-Up",description:"Write an appeal that succeeds, and manage accounts receivable so claims do not age into worthlessness.",duration:"22 min",objectives:["Write a structured appeal letter","Describe the levels of appeal available","Run and interpret an A/R aging report","Decide when a balance should be written off"],sections:[{heading:"An appeal is an argument with evidence",blocks:[{type:"scenario",role:"You appeal a medical necessity denial at Lakeside Medical Associates.",text:"The first attempt was two sentences asking the payer to reconsider. It was upheld. The service was genuinely appropriate and the documentation supports it — the appeal simply never said so in a form the reviewer could act on.",task:"Write appeals that make the case rather than merely register disagreement."},{type:"paragraph",text:"A successful appeal states what was denied, why the denial is wrong, what evidence supports that, and what you are asking for. A reviewer working through a stack of appeals should be able to reach the point in the first paragraph."},{type:"table",caption:"Structure of an effective appeal",columns:["Section","Contains"],rows:[["Identification","Patient, member ID, claim number, date of service, denied amount"],["The denial","The reason code and the payer's stated reason, quoted"],["The argument","Why the denial is incorrect, tied to the documentation"],["The evidence","The records, guidelines, or policy language attached"],["The request","The specific action sought — reprocess and pay the claim"]]},{type:"paragraph",text:"Most payers offer several levels of appeal, each with its own deadline. A first-level appeal is typically an internal reconsideration. A second level may involve a different reviewer or a peer-to-peer discussion with a physician. Some plans, and Medicare in particular, provide independent external review beyond that. Each level has a window, and missing one usually forecloses the rest."},{type:"table",caption:"Reading an A/R aging report",columns:["Bucket","Interpretation","Action"],rows:[["0-30 days","Normal processing","Monitor only"],["31-60 days","Slower than expected","Check status; confirm the payer received it"],["61-90 days","Something is wrong","Work actively; a denial may have gone unnoticed"],["91-120 days","Recovery becoming unlikely","Escalate; check filing and appeal deadlines"],["120+ days","Often uncollectible","Determine whether to pursue or write off"]]},{type:"callout",variant:"warning",text:"Writing off a balance is a decision with rules, not a way to clear a queue. A contractual adjustment is required by the payer contract. A bad debt write-off follows genuine collection effort. Writing off a collectible balance to tidy the aging report misstates the practice's revenue, and routinely waiving patient responsibility that a plan requires you to collect can violate your payer contracts and, for federal programs, implicate the anti-kickback statute. Write-offs should follow a written policy and be approved, not made ad hoc by whoever is working the queue."},{type:"knowledge-check",question:"A first-level appeal on a medical necessity denial is upheld. The documentation genuinely supports the service. What is the appropriate next step?",options:["Write the balance off, since the payer has now refused twice","Escalate to the next level of appeal within its deadline, adding any evidence the first appeal lacked","Bill the patient for the full amount","Resubmit the original claim unchanged"],correctIndex:1,explanation:"A first-level denial is not the end of the process. Most payers provide further levels, often including peer-to-peer review, and each has its own deadline. If the documentation supports the service, escalating with a strengthened argument is the correct route.",optionRationales:["Writing off a supportable claim forfeits revenue the practice legitimately earned.","Correct. Escalate within the deadline and strengthen the evidence.","The patient is not responsible for a payer's medical necessity determination, and billing them may breach the payer contract.","Resubmitting unchanged produces the same denial or a duplicate rejection, while the appeal window runs out."]}]}],challenge:[{type:"paragraph",text:"Write a real appeal and read a real aging report."},{type:"list",ordered:!0,items:["Write a complete appeal letter using the five-section structure, for a medical necessity denial on a service you invent. Keep it to one page.","Research the appeal levels one major payer offers, and note the deadline for each.","Given total A/R of $412,000 with $94,000 over 90 days, calculate the percentage over 90 days and state whether it falls inside a 15-20% target.","Draft a short write-off policy naming who may approve a write-off, what documentation is required, and which categories are eligible."]}]}],level:"Advanced",estimatedMinutes:48,whatYoullLearn:["Interpreting denial reason codes and categorizing by root cause","Choosing between a corrected claim, an appeal, and a write-off","Prioritizing a denial queue by deadline and dollar value","Writing a structured appeal, and reading an A/R aging report"],scenario:"You inherit 138 denials worth $47,000. Working them oldest-first would be reasonable if they were equivalent — but some are worth $40 and some $3,000, some are five days from a filing deadline, and roughly a third have no realistic prospect of recovery at all."},{moduleNumber:8,moduleSlug:"module-8",title:"Compliance & Ethics",emoji:"⚖️",description:"The privacy rules governing everything you touch, the laws governing claim submission, and what to do when you are asked to code something you cannot support.",lessons:[{slug:"hipaa-for-billing",title:"HIPAA for Billing and Coding",description:"Understand the privacy and security obligations that govern everything a billing professional touches.",duration:"24 min",objectives:["Identify what counts as protected health information","Apply the minimum necessary standard","Explain what disclosures are permitted for payment operations","Recognize a breach and know the reporting obligation"],sections:[{heading:"You handle protected information all day",blocks:[{type:"scenario",role:"You work in billing at Lakeside Medical Associates.",text:"In one morning you handle a patient's name, date of birth, diagnosis codes, dates of service, insurance identifiers, and payment history. Every one of those is protected health information, and the fact that your work is administrative rather than clinical changes nothing about your obligations.",task:"Understand what you are handling and the rules that govern it."},{type:"paragraph",text:"Protected health information is individually identifiable health information held or transmitted by a covered entity. Billing data is squarely within it — a claim links a person to a diagnosis, which is exactly the kind of association the rules exist to protect."},{type:"paragraph",text:"HIPAA permits disclosure without patient authorization for treatment, payment, and health care operations. Billing sits in the payment category, which is why you may send a claim carrying a diagnosis to a payer. That permission is specific, not general: it covers what payment requires and nothing beyond it."},{type:"table",caption:"The minimum necessary standard in practice",columns:["Situation","Appropriate","Not appropriate"],rows:[["Submitting a claim","The codes and identifiers the claim requires","The complete clinical record attached by default"],["Responding to a payer records request","Records for the dates and services in question","The entire chart because it is easier to send"],["Discussing an account with a colleague","What they need to resolve the issue","Details unrelated to the question"],["Looking up a record","Accounts you are assigned to work","A neighbour's or coworker's record out of curiosity"]]},{type:"callout",variant:"warning",text:"Accessing a record you have no work reason to see is a violation even if you tell no one and change nothing. Access is logged, audits are routine, and curiosity about a coworker's, neighbour's, or public figure's record is among the most common causes of termination in healthcare administration. There is no version of this that is harmless."},{type:"paragraph",text:"A breach is an impermissible use or disclosure that compromises the security or privacy of protected health information. Emailing a claim to the wrong address, leaving a report on a printer, discussing an account where it can be overheard, and losing an unencrypted device all qualify. Report a suspected breach immediately to your privacy officer — the reporting obligation has deadlines, and delay makes every outcome worse."},{type:"knowledge-check",question:"A payer requests records to support one claim for a single date of service. What should be sent?",options:["The complete patient chart, so the reviewer has full context","Only the records for the date of service and the services at issue","Nothing without written patient authorization","A summary written by the biller rather than the actual records"],correctIndex:1,explanation:"The minimum necessary standard limits disclosure to what the purpose requires. The purpose is supporting one claim, so records for that date and those services are appropriate. Sending the whole chart discloses far more than the payer needs or is entitled to.",optionRationales:["Sending the full chart exceeds minimum necessary and discloses unrelated information.","Correct. Disclose what the specific purpose requires and no more.","Disclosure for payment purposes does not require separate patient authorization.","A biller's summary is not the medical record and cannot substitute for it in a payer review."]}]}],challenge:[{type:"paragraph",text:"Apply the standard to situations you will actually face."},{type:"list",ordered:!0,items:["List the eighteen HIPAA identifiers. Note which ones appear on a routine claim.","For each of these, decide whether it is a breach and justify it: a claim emailed to the wrong payer address; a report left on a shared printer overnight; discussing an account with the treating provider; looking up a coworker's balance out of concern for them.","Write a three-sentence description of the minimum necessary standard as you would explain it to a new colleague.","Find your organization's or a sample breach reporting procedure. Note who to contact and within what timeframe."]}]},{slug:"fraud-abuse-and-compliance",title:"Fraud, Abuse, and Compliance",description:"Understand the laws governing claim submission, the difference between an error and fraud, and what to do when you are asked to code something you cannot support.",duration:"26 min",objectives:["Distinguish fraud from abuse from an honest error","Describe the major laws governing healthcare claims","Identify common fraudulent billing patterns","Know how to respond when asked to submit something unsupportable"],sections:[{heading:"Intent is what separates error from fraud",blocks:[{type:"scenario",role:"You code for a provider at Lakeside Medical Associates.",text:"A provider asks you to change a 99213 to a 99215 on a note that plainly does not support it, saying the visit 'felt like a level five' and the practice is behind on revenue. Refusing is uncomfortable. Complying would make you a participant in submitting a false claim, and 'my supervisor told me to' has never been a defence.",task:"Know the law well enough to recognize the line, and know the process for what to do when you are asked to cross it."},{type:"table",caption:"Error, abuse, and fraud",columns:["","Means","Example"],rows:[["Error","An unintentional mistake","A transposed code digit; a modifier omitted in haste"],["Abuse","Practices inconsistent with sound billing that result in unnecessary cost, without proven intent to deceive","Systematically billing a higher level without deliberate falsification"],["Fraud","Knowing misrepresentation to obtain payment not entitled to","Billing for services never rendered; deliberately upcoding"]]},{type:"paragraph",text:"The distinction turns largely on knowledge and intent. Errors are expected and corrected. Fraud requires knowing that the claim misrepresents what happened — which is why a coder who understands the rules and submits anyway is in a very different position from one who made a mistake."},{type:"table",caption:"The laws that apply",columns:["Law","Prohibits","Note"],rows:[["False Claims Act","Knowingly submitting false claims to the government","Substantial per-claim penalties plus multiplied damages; includes whistleblower provisions"],["Anti-Kickback Statute","Paying or receiving anything of value for referrals of federally funded services","Criminal statute; intent-based"],["Stark Law","Physician referrals to entities they have a financial relationship with, for designated services","Strict liability — intent is not required"],["HIPAA","Improper use and disclosure of protected health information","Civil and, for knowing misuse, criminal penalties"],["Exclusion authority","Excluded individuals participating in federal programs","Exclusion effectively ends a healthcare career"]]},{type:"table",caption:"Patterns that draw scrutiny",columns:["Pattern","What it is"],rows:[["Upcoding","Reporting a higher-paying code than the documentation supports"],["Unbundling","Billing components separately when a comprehensive code exists"],["Billing for services not rendered","Claiming work that never happened"],["Misrepresenting the provider","Billing a mid-level provider's service under a physician's NPI improperly"],["Cloned documentation","Identical notes across encounters, suggesting they do not reflect real visits"],["Routine waiver of copays","Systematically not collecting patient responsibility"]]},{type:"worked-example",title:"When you are asked to code something unsupportable",task:"Respond to a provider's request to change a 99213 to a 99215 on documentation that does not support it.",steps:[{move:"Assume good faith and treat it as a documentation question first.",why:"Providers are often genuinely unaware of what the level requires, and the visit may well have involved work that was simply not written down. Framing it as 'the note does not currently support 99215 — was there more?' opens the legitimate route rather than starting a confrontation."},{move:"Offer the proper mechanism: amend the documentation.",why:"If the work genuinely occurred, the provider may amend the note through the record's amendment process, with the amendment dated and attributed. A properly amended note supporting the higher level makes the higher code correct. This is the real solution, and it is available."},{move:"If the answer is that the work did not occur, decline clearly and without hostility.",why:"'I can't code above what the documentation supports' is a complete answer. You are not accusing anyone; you are stating the rule you work by. Most requests end here."},{move:"If pressed, escalate through the compliance process rather than deciding alone.",why:"Every practice should have a compliance officer or designated escalation route. Using it protects the practice, the provider, and you — and creates a record that you raised it, which matters a great deal if the pattern is later investigated."},{move:"Document what was asked and what you did.",why:"A dated note of the request and your response is your protection. In a False Claims Act investigation, the question of who knew what becomes central, and contemporaneous records are worth far more than recollection."}],result:"Either a properly amended note supporting the higher code, or the original code standing, with the exchange documented.",takeaway:"Treat it as a documentation question, offer the legitimate route, decline clearly if there is none, escalate rather than deciding alone, and write it down."},{type:"callout",variant:"warning",text:"Following instructions is not a defence. A coder who submits a claim they know the documentation does not support has knowingly participated in submitting a false claim, regardless of who directed it. The False Claims Act also has whistleblower provisions, meaning colleagues have both protection and financial incentive to report. Your signature on the work is yours."},{type:"knowledge-check",question:"A provider directs you to bill a level of service the documentation does not support. You comply. What is your position?",options:["Protected, since you were following a supervisor's direction","Exposed — knowingly submitting a claim the documentation does not support is participating in a false claim, whoever directed it","Responsible only if the payer detects it","Not responsible, since the provider is accountable for the documentation"],correctIndex:1,explanation:"Liability under the False Claims Act attaches to knowingly submitting a false claim. A coder who understands the rules and submits anyway has the requisite knowledge, and direction from a supervisor does not remove it. The correct response is to offer the amendment route and escalate through compliance.",optionRationales:["Following orders is not a recognized defence to knowingly submitting a false claim.","Correct. Knowledge is what creates exposure, and you had it.","Liability arises from the submission, not from whether it is caught.","The provider is accountable for documentation, and the coder is accountable for coding to it. Both are exposed."]}]}],challenge:[{type:"paragraph",text:"Know the process before you need it."},{type:"list",ordered:!0,items:["Research the seven elements of an effective compliance program as described by the OIG. Summarize each in one sentence.","Find the OIG exclusion list (LEIE) and describe what it is used for and how often a practice should check it.","Write out, word for word, what you would say to a provider asking you to code above the documentation. Keep it to three sentences and make it non-confrontational.","Describe the escalation path you would follow if the request were repeated after you declined, and what you would document at each step."]}]}],level:"Advanced",estimatedMinutes:50,whatYoullLearn:["What counts as protected health information, and the minimum necessary standard","Recognizing a breach and the obligation to report it","The False Claims Act, Anti-Kickback Statute, and Stark Law","How to respond when directed to submit a claim the documentation does not support"],scenario:"A provider asks you to change a 99213 to a 99215 on a note that plainly does not support it, saying the visit 'felt like a level five' and the practice is behind on revenue. Refusing is uncomfortable. Complying would make you a participant in submitting a false claim — and 'my supervisor told me to' has never been a defence."}]}],e=Object.fromEntries(d.map(a=>[a.slug,a]))}};